{
  "name": "pi-memory-workbench",
  "version": "0.1.0",
  "description": "Durable, session-safe Markdown memory for the Pi coding agent.",
  "private": true,
  "type": "module",
  "license": "MIT",
  "author": "Nico Bailon",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicobailon/pi-memory-workbench.git"
  },
  "homepage": "https://github.com/nicobailon/pi-memory-workbench#readme",
  "bugs": {
    "url": "https://github.com/nicobailon/pi-memory-workbench/issues"
  },
  "keywords": [
    "pi-package",
    "pi-coding-agent",
    "memory",
    "markdown",
    "agent"
  ],
  "pi": {
    "extensions": [
      "./index.ts"
    ]
  },
  "scripts": {
    "test": "bun test",
    "check": "node --check index.ts && node --check memory.ts && node --check memory-recall.ts && node --check memory-schema.ts && node --check memory-events.ts && node --check memory-digest.ts && node --check memory-lint.ts && node --check paths.ts && node --check todo.ts && node --check todo-widget.ts"
  },
  "peerDependencies": {
    "@earendil-works/pi-ai": "*",
    "@earendil-works/pi-coding-agent": "*",
    "@earendil-works/pi-tui": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-ai": { "optional": true },
    "@earendil-works/pi-coding-agent": { "optional": true },
    "@earendil-works/pi-tui": { "optional": true },
    "typebox": { "optional": true }
  }
}

import { afterEach, describe, expect, mock, test } from "bun:test";
import { mkdtemp, mkdir, readFile, readdir, rm, symlink, utimes, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { MemoryCandidate } from "../memory-schema.ts";
import type { MemoryPaths } from "../paths.ts";
import type { MemoryState } from "../memory.ts";

mock.module("@earendil-works/pi-coding-agent", () => ({
	withFileMutationQueue: async (_path: string, operation: () => Promise<unknown>) => operation(),
}));

const { createMemoryDigest } = await import("../memory-digest.ts");
const { expandMemorySource, formatMemoryRecall, recallMemory } = await import("../memory-recall.ts");
const { buildDeterministicCompactionCheckpoint, projectMemoryHotView, writeCompactionCheckpoint } = await import("../memory.ts");
const { formatMemoryEventMetadataV1, parseMemoryEventMetadata } = await import("../memory-events.ts");
const { applyDreamMemoryCandidates, extractMemoryCandidates, parseProjectMemorySchema } = await import("../memory-schema.ts");
const { MEMORY_LAYOUT_MARKER, fileSnapshot, hashContent } = await import("../paths.ts");

const temporaryDirectories: string[] = [];

afterEach(async () => {
	await Promise.all(temporaryDirectories.splice(0).map((path) => rm(path, { recursive: true, force: true })));
});

describe("event metadata", () => {
	test("round-trips provenance and references", () => {
		const content = formatMemoryEventMetadataV1({
			kind: "checkpoint",
			created: "2026-07-25T12:00:00.000Z",
			sessionId: "session-1",
			actorKind: "owner",
			project: "workbench",
			sessionProgress: "sessions/session-1/progress.md",
			sessionTodo: "sessions/session-1/todo.md",
			memory: "memory.md",
			sourceHashes: [{ path: "memory.md", hash: "sha256:abc" }],
			relatedEvents: { previousEvent: "events/previous.md" },
			memoryRefs: ["memory.md#decisions (dec-1234)"],
			digestRefs: ["event-digests/digest.md"],
		});

		const parsed = parseMemoryEventMetadata(`# Memory Event\n\n${content}\n\n## Summary\nDone.`);
		expect(parsed.version).toBe("v1");
		expect(parsed.kind).toBe("checkpoint");
		expect(parsed.actorKind).toBe("owner");
		expect(parsed.sourceHashes).toEqual([{ path: "memory.md", hash: "sha256:abc" }]);
		expect(parsed.relatedEvents.previousEvent).toBe("events/previous.md");
		expect(parsed.memoryRefs).toEqual(["memory.md#decisions (dec-1234)"]);
		expect(parsed.digestRefs).toEqual(["event-digests/digest.md"]);
	});
});

describe("Dream candidate extraction", () => {
	test("reads semantic event sections without ingesting metadata", () => {
		const metadata = formatMemoryEventMetadataV1({
			kind: "checkpoint",
			created: "2026-07-25T12:00:00.000Z",
			sessionId: "session-1",
			actorKind: "owner",
			project: "workbench",
			sessionProgress: "sessions/session-1/progress.md",
			sessionTodo: "sessions/session-1/todo.md",
			memory: "memory.md (missing)",
			sourceHashes: [{ path: "sessions/session-1/progress.md", hash: "sha256:abc" }],
		});
		const candidates = extractMemoryCandidates([{
			kind: "event",
			path: "events/checkpoint.md",
			content: `# Memory Event\n\n${metadata}\n\n## Summary\nDecision: Raw events remain authoritative.\n\n## Current State\n- sessions/session-1/progress.md\n- memory.md (missing)\n`,
		}]);

		expect(candidates.map((candidate) => candidate.text)).toEqual(["Decision: Raw events remain authoritative."]);
	});

	test("ignores existing memory as a candidate source", () => {
		const candidates = extractMemoryCandidates([{
			kind: "memory",
			path: "memory.md",
			content: "## Conventions\n- Shared progress.md is dashboard-only.\n",
		}]);
		expect(candidates).toEqual([]);
	});

	test("keeps durable progress updates and concrete verification without ingesting active Resume Here state", () => {
		const candidates = extractMemoryCandidates([{
			kind: "session-progress",
			path: "sessions/session-1/progress.md",
			content: "## Resume Here\n- Current objective: Rewrite memory.md.\n- Current state: Working in memory-schema.ts.\n- Active files: memory-schema.ts\n- Last verified command: `npm test` passed.\n\n## Updates\n- sessions/session-1/progress.md\n- memory.md (missing)\n- sha256:0123456789abcdef\n- Decision: Keep raw events immutable.\n",
		}]);
		expect(candidates.map((candidate) => candidate.text)).toEqual(["Decision: Keep raw events immutable.", "Last verified command: `npm test` passed."]);
	});
});

describe("memory recall", () => {
	test("searches bounded project sources and honors scope and metadata filters", async () => {
		const paths = await temporaryMemoryPaths();
		await writeFile(paths.memoryPath, "# Project Memory\n\n## Decisions\n- Immutable raw events remain the authoritative durable evidence.\n", "utf8");
		await writeFile(paths.sessionProgressPath, "# Progress\n\n## Updates\n- Added bounded memory recall search.\n", "utf8");
		const otherSessionDir = join(paths.sessionsDir, "session-2");
		await mkdir(otherSessionDir, { recursive: true });
		await writeFile(join(otherSessionDir, "progress.md"), "# Other Progress\n\n## Updates\n- Unrelated release planning.\n", "utf8");
		await writeEvent(paths, "current.md", "session-1", "checkpoint", "Verified immutable event recall behavior.");
		await writeEvent(paths, "other.md", "session-2", "todo", "Unrelated todo event.");
		const state = recallState(paths);

		const project = await recallMemory(state, { query: "immutable event", scope: "project", limit: 2 });
		expect(project.hits).toHaveLength(2);
		expect(project.hits.map((hit) => hit.path)).toContain("memory.md");
		expect(project.totalMatches).toBeGreaterThanOrEqual(2);
		expect(formatMemoryRecall(project)).toContain("Use memory_recall with path");

		const memoryOnly = await recallMemory(state, { query: "authoritative evidence", scope: "memory" });
		expect(memoryOnly.totalDocuments).toBe(1);
		expect(memoryOnly.hits.map((hit) => hit.path)).toEqual(["memory.md"]);

		const sessionOnly = await recallMemory(state, { query: "recall", scope: "session" });
		expect(sessionOnly.hits.every((hit) => hit.sessionId === "session-1")).toBe(true);
		expect(sessionOnly.hits.some((hit) => hit.path === "sessions/session-2/progress.md")).toBe(false);

		const checkpoints = await recallMemory(state, { query: "event", scope: "events", kind: "checkpoint" });
		expect(checkpoints.hits).toHaveLength(1);
		expect(checkpoints.hits[0]?.kind).toBe("checkpoint");
	});

	test("uses the raw session ID for filters even when its directory name is sanitized", async () => {
		const paths = await temporaryMemoryPaths();
		await writeFile(paths.sessionProgressPath, "# Progress\n\nSession ID: raw/session id\n\n## Updates\n- Added recall filtering.\n", "utf8");
		const state = {
			...recallState(paths),
			session: { id: "raw/session id", safeId: "session-1", actorKind: "owner", memoryMode: "owner" },
		} as MemoryState;
		const result = await recallMemory(state, { query: "recall", scope: "session", sessionId: "raw/session id" });
		expect(result.hits.map((hit) => hit.path)).toContain("sessions/session-1/progress.md");
		expect(result.hits[0]?.sessionId).toBe("raw/session id");
	});

	test("expands only exact searchable project sources", async () => {
		const paths = await temporaryMemoryPaths();
		await writeFile(paths.memoryPath, "# Project Memory\n\nDurable source.\n", "utf8");
		const state = recallState(paths);
		const expanded = await expandMemorySource(state, "memory.md");
		expect(expanded.content).toContain("Durable source.");
		expect(expanded.truncated).toBe(false);
		await expect(expandMemorySource(state, "../outside.md")).rejects.toThrow("must stay inside");
		await expect(expandMemorySource(state, "progress.md")).rejects.toThrow("not a searchable workbench artifact");
	});

	test("refuses searchable artifacts that resolve outside the project through a symlink", async () => {
		const paths = await temporaryMemoryPaths();
		const outsideDir = await mkdtemp(join(tmpdir(), "pi-memory-outside-"));
		temporaryDirectories.push(outsideDir);
		const outside = join(outsideDir, "outside.md");
		await writeFile(outside, "# Outside\n\nsecret material\n", "utf8");
		await symlink(outside, paths.memoryPath);
		await expect(recallMemory(recallState(paths), { query: "secret", scope: "memory" })).rejects.toThrow("resolves outside");
	});
});

describe("durable memory", () => {
	test("remains stable across 100 repeated Dream applications", async () => {
		const paths = await temporaryMemoryPaths();
		const candidate: MemoryCandidate = {
			text: "Session progress is authoritative; shared progress.md is dashboard-only.",
			section: "Conventions",
			sources: ["events/checkpoint.md"],
		};
		let stableHash = "";

		for (let run = 0; run < 100; run += 1) {
			const result = await applyDreamMemoryCandidates({
				paths,
				expected: await fileSnapshot(paths.memoryPath),
				candidates: [candidate],
				now: "2026-07-25T12:00:00.000Z",
			});
			const content = await readFile(paths.memoryPath, "utf8");
			if (run === 0) {
				expect(result.applied).toHaveLength(1);
				stableHash = hashContent(content);
			} else {
				expect(result.applied).toHaveLength(0);
				expect(result.skippedDuplicates).toHaveLength(1);
				expect(hashContent(content)).toBe(stableHash);
			}
		}

		const parsed = parseProjectMemorySchema(await readFile(paths.memoryPath, "utf8"));
		expect(parsed.entries.filter((entry) => entry.section === "Conventions")).toHaveLength(1);
	});

	test("supersedes an existing fact only through an explicit known memory ID", async () => {
		const paths = await temporaryMemoryPaths();
		const first = await applyDreamMemoryCandidates({
			paths,
			expected: await fileSnapshot(paths.memoryPath),
			candidates: [{ text: "Shared progress.md is authoritative.", section: "Conventions", sources: ["events/old.md"] }],
			now: "2026-07-24T12:00:00.000Z",
		});
		const oldId = first.applied[0]?.id;
		expect(oldId).toBeTruthy();
		const extracted = extractMemoryCandidates([{
			kind: "event",
			path: "events/new.md",
			content: `## Conventions\n- [supersedes: ${oldId}] Session progress.md is authoritative; shared progress.md is dashboard-only.\n`,
		}]);
		expect(extracted[0]?.supersedes).toBe(oldId);

		const replacement = await applyDreamMemoryCandidates({
			paths,
			expected: await fileSnapshot(paths.memoryPath),
			candidates: extracted,
			now: "2026-07-25T12:00:00.000Z",
		});
		expect(replacement.applied).toHaveLength(1);
		expect(replacement.superseded).toHaveLength(1);
		const replacementId = replacement.applied[0]?.id;
		const parsed = parseProjectMemorySchema(await readFile(paths.memoryPath, "utf8"));
		const oldEntry = parsed.entries.find((entry) => entry.id === oldId);
		const newEntry = parsed.entries.find((entry) => entry.id === replacementId);
		expect(oldEntry?.status).toBe("superseded");
		expect(oldEntry?.supersededBy).toBe(replacementId);
		expect(newEntry?.status).toBe("active");

		const repeated = await applyDreamMemoryCandidates({
			paths,
			expected: await fileSnapshot(paths.memoryPath),
			candidates: extracted,
			now: "2026-07-25T12:00:00.000Z",
		});
		expect(repeated.applied).toHaveLength(0);
		expect(repeated.skippedDuplicates).toHaveLength(1);
		expect(repeated.superseded).toHaveLength(0);
	});

	test("does not supersede an active fact with an existing Deferred entry", async () => {
		const paths = await temporaryMemoryPaths();
		const seeded = await applyDreamMemoryCandidates({
			paths,
			expected: await fileSnapshot(paths.memoryPath),
			candidates: [
				{ text: "Use the active convention.", section: "Conventions", sources: ["events/active.md"] },
				{ text: "Potential replacement convention.", section: "Deferred", sources: ["events/deferred.md"], reason: "manual review required" },
			],
			now: "2026-07-24T12:00:00.000Z",
		});
		const activeId = seeded.applied[0]?.id as string;
		const result = await applyDreamMemoryCandidates({
			paths,
			expected: await fileSnapshot(paths.memoryPath),
			candidates: [{ text: "Potential replacement convention.", section: "Conventions", sources: ["events/new.md"], supersedes: activeId }],
			now: "2026-07-25T12:00:00.000Z",
		});
		const parsed = parseProjectMemorySchema(await readFile(paths.memoryPath, "utf8"));
		expect(result.superseded).toHaveLength(0);
		expect(parsed.entries.find((entry) => entry.id === activeId)?.status).toBe("active");
	});

	test("defers supersession when the target memory ID is unknown", async () => {
		const paths = await temporaryMemoryPaths();
		const result = await applyDreamMemoryCandidates({
			paths,
			expected: await fileSnapshot(paths.memoryPath),
			candidates: [{
				text: "Use a new durable convention.",
				section: "Conventions",
				sources: ["events/new.md"],
				supersedes: "conv-deadbeef",
			}],
			now: "2026-07-25T12:00:00.000Z",
		});
		expect(result.applied).toHaveLength(0);
		expect(result.superseded).toHaveLength(0);
		expect(result.deferred[0]?.reason).toContain("unknown memory id");
	});

	test("preserves a malformed marker-bearing file as legacy content", async () => {
		const paths = await temporaryMemoryPaths();
		const malformed = "# Notes\n\nImportant top-level content.\n\n```md\n<!-- pi-memory-workbench-memory: v1 -->\n```\n\n## Conventions\n\n## Decisions\n- Keep this partial decision.\n\n## Verified Commands\n\n## Gotchas\n\n## Avoid\n\n## Deferred\n";
		await writeFile(paths.memoryPath, malformed, "utf8");
		await applyDreamMemoryCandidates({
			paths,
			expected: await fileSnapshot(paths.memoryPath),
			candidates: [],
			now: "2026-07-25T12:00:00.000Z",
		});
		const content = await readFile(paths.memoryPath, "utf8");
		expect(content).toContain("## Legacy Memory");
		expect(content).toContain("Important top-level content.");
		expect(content).toContain("Keep this partial decision.");
	});

	test("preserves freeform memory during the first schema-v1 update", async () => {
		const paths = await temporaryMemoryPaths();
		await writeFile(paths.memoryPath, "# Notes\n\n- Keep this original note.\n", "utf8");
		const result = await applyDreamMemoryCandidates({
			paths,
			expected: await fileSnapshot(paths.memoryPath),
			candidates: [],
			now: "2026-07-25T12:00:00.000Z",
		});
		const content = await readFile(paths.memoryPath, "utf8");

		expect(result.legacyPreserved).toBe(true);
		expect(content).toContain("## Legacy Memory");
		expect(content).toContain("Keep this original note.");
	});
});

describe("bounded memory view", () => {
	test("shows a balanced active subset with stable recall anchors", () => {
		const content = `# Project Memory\n<!-- pi-memory-workbench-memory: v1 -->\n\n## Conventions\n- [id: conv-00000001] Old convention. (source: a; seen: 2026-01-01)\n- [id: conv-00000002] Current convention one. (source: b; seen: 2026-01-02)\n- [id: conv-00000003] Superseded convention. (source: c; seen: 2026-01-03; status: superseded; superseded-by: conv-00000004; superseded: 2026-01-04)\n- [id: conv-00000004] Current convention two. (source: d; seen: 2026-01-04)\n\n## Decisions\n- [id: dec-00000001] First decision. (source: e; seen: 2026-01-01)\n- [id: dec-00000002] Second decision. (source: f; seen: 2026-01-02)\n- [id: dec-00000003] Third decision. (source: g; seen: 2026-01-03)\n\n## Verified Commands\n\n## Gotchas\n\n## Avoid\n\n## Deferred\n- [id: def-00000001] Deferred noise. (deferred: review; source: h; seen: 2026-01-01)\n`;
		const view = projectMemoryHotView(content, 2);

		expect(view).toContain("[Conventions: conv-00000002]");
		expect(view).toContain("[Conventions: conv-00000004]");
		expect(view).toContain("[Decisions: dec-00000002]");
		expect(view).toContain("[Decisions: dec-00000003]");
		expect(view).not.toContain("Superseded convention");
		expect(view).not.toContain("Deferred noise");
		expect(view).toContain("2 active entries omitted");
		expect(view).toContain("memory_recall");
	});
});

describe("deterministic compaction fallback", () => {
	test("extracts continuation fields from a structured native summary and notable activity", async () => {
		const paths = await temporaryMemoryPaths();
		const state = {
			...recallState(paths),
			progress: "# Progress\n\n## Resume Here\n- Current objective: Old objective.\n- Current state: Old state.\n- Next action: Old next action.\n- Blockers/open questions: Old blocker.\n- Last verified command: Old verification.\n",
			activeTodoPath: paths.sessionTodoPath,
		} as MemoryState;
		const checkpoint = buildDeterministicCompactionCheckpoint(state, {
			summary: "## Goal\nImplement durable memory recall.\n\n## Current State\nRecall and lifecycle tests pass.\n\n## Next Steps\n- Reload Pi and exercise memory_recall.\n\n## Verification\n`npm test` passed.\n\n## Blockers\nNone.\n\n## Files\n- memory-recall.ts\n",
			notableActivity: "File edits:\n- edit memory-schema.ts\n- write memory-recall.ts\n\nRead files:\n- read README.md",
			reason: "Focused checkpoint model unavailable.",
		});

		expect(checkpoint.objective).toBe("Implement durable memory recall.");
		expect(checkpoint.currentState).toBe("Recall and lifecycle tests pass.");
		expect(checkpoint.nextAction).toBe("Reload Pi and exercise memory_recall.");
		expect(checkpoint.blockers).toBe("None.");
		expect(checkpoint.lastVerifiedCommand).toBe("`npm test` passed.");
		expect(checkpoint.activeFiles).toEqual(["memory-recall.ts", "memory-schema.ts", "README.md"]);
		expect(checkpoint.progressUpdate).toContain("deterministic fallback");
	});

	test("writes the reconstructed Resume Here and an immutable fallback event", async () => {
		const paths = await temporaryMemoryPaths();
		const progress = "# Progress\n\n## Resume Here\n- Current objective: Old objective.\n- Current state: Old state.\n- Next action: Old next action.\n- Active todo file: None.\n- Active files: None recorded.\n- Blockers/open questions: None.\n- Last verified command: Not recorded.\n\n## Updates\n";
		const dashboard = `${MEMORY_LAYOUT_MARKER}\n# Progress Dashboard\n`;
		await writeFile(paths.sessionProgressPath, progress, "utf8");
		await writeFile(paths.progressPath, dashboard, "utf8");
		const state = {
			...recallState(paths),
			dashboard,
			progress,
			recentEvents: [],
			recentSessions: [],
			hashes: {
				dashboard: await fileSnapshot(paths.progressPath),
				sessionProgress: await fileSnapshot(paths.sessionProgressPath),
				sessionTodo: await fileSnapshot(paths.sessionTodoPath),
				memory: await fileSnapshot(paths.memoryPath),
			},
			dream: { state: "never" },
		} as MemoryState;
		const result = await writeCompactionCheckpoint(state, 1234, "No model selected.", "## Goal\nRecovered objective.\n\n## Next Steps\nRun verification.\n", "File edits:\n- edit memory.ts");

		const updated = await readFile(paths.sessionProgressPath, "utf8");
		expect(updated).toContain("- Current objective: Recovered objective.");
		expect(updated).toContain("- Next action: Run verification.");
		expect(updated).toContain("- Active files: memory.ts");
		const eventContent = await readFile(result.eventPath as string, "utf8");
		expect(parseMemoryEventMetadata(eventContent).kind).toBe("compaction-fallback");
		expect(eventContent).toContain("## Objective\nRecovered objective.");
	});

	test("keeps known objective and next action when an unstructured summary cannot replace them", async () => {
		const paths = await temporaryMemoryPaths();
		const state = {
			...recallState(paths),
			progress: "# Progress\n\n## Resume Here\n- Current objective: Preserve this objective.\n- Current state: Existing state.\n- Next action: Preserve this next action.\n- Blockers/open questions: None.\n- Last verified command: Not recorded.\n",
		} as MemoryState;
		const checkpoint = buildDeterministicCompactionCheckpoint(state, {
			summary: "The conversation was compacted after a long implementation session.",
			notableActivity: "No notable activity captured.",
			reason: "No model selected.",
		});

		expect(checkpoint.objective).toBe("Preserve this objective.");
		expect(checkpoint.nextAction).toBe("Preserve this next action.");
		expect(checkpoint.currentState).toBe("The conversation was compacted after a long implementation session.");
		expect(checkpoint.activeFiles).toEqual([]);
	});
});

describe("event digests", () => {
	test("retain raw events and exclude the newest tail", async () => {
		const paths = await temporaryMemoryPaths();
		const oldTime = new Date("2026-01-01T00:00:00.000Z");
		const original = new Map<string, string>();
		for (let index = 0; index < 150; index += 1) {
			const name = `20260101T000000Z-session-checkpoint-${String(index).padStart(3, "0")}.md`;
			const path = join(paths.eventsDir, name);
			const content = `# Memory Event\n\nKind: checkpoint\nSession ID: session-1\n\n## Summary\nCheckpoint ${index}.\n`;
			await writeFile(path, content, "utf8");
			await utimes(path, oldTime, oldTime);
			original.set(name, content);
		}

		const state = {
			paths,
			dashboard: `${MEMORY_LAYOUT_MARKER}\n# Progress Dashboard\n`,
			session: { id: "session-1", safeId: "session-1", actorKind: "owner", memoryMode: "owner" },
		} as MemoryState;
		const result = await createMemoryDigest(state);

		expect(result.sourceEventCount).toBe(100);
		expect(result.completeThrough).toEndWith("checkpoint-099.md");
		expect(await readdir(paths.eventsDir)).toHaveLength(150);
		for (const [name, content] of original) {
			expect(await readFile(join(paths.eventsDir, name), "utf8")).toBe(content);
		}
		const digest = await readFile(result.path, "utf8");
		expect(digest).toContain("Source event count: 100");
		expect(digest).toContain("Excludes newest event tail: 50");
		expect(digest).toContain("Raw events were not edited, moved, deleted, or marked.");
	});
});

function recallState(paths: MemoryPaths): MemoryState {
	return {
		paths,
		session: { id: "session-1", safeId: "session-1", actorKind: "owner", memoryMode: "owner" },
	} as MemoryState;
}

async function writeEvent(paths: MemoryPaths, name: string, sessionId: string, kind: string, summary: string): Promise<void> {
	const metadata = formatMemoryEventMetadataV1({
		kind,
		created: "2026-07-25T12:00:00.000Z",
		sessionId,
		actorKind: "owner",
		project: paths.projectKey,
		sessionProgress: `sessions/${sessionId}/progress.md`,
		sessionTodo: `sessions/${sessionId}/todo.md`,
