import { createHash } from "node:crypto";
import { readdir, stat } from "node:fs/promises";
import { basename, join, parse } from "node:path";
import { parseMemoryEventMetadata } from "./memory-events.ts";
import { extractMemoryCandidates, type MemorySource } from "./memory-schema.ts";
import {
	MEMORY_LAYOUT_MARKER,
	hashContent,
	readOptional,
	relativeFrom,
	writeExclusiveFile,
	type MemoryPaths,
} from "./paths.ts";
import type { MemoryState } from "./memory.ts";

export const DIGEST_RECENT_EVENT_TAIL = 50;
export const DIGEST_MIN_EVENT_AGE_HOURS = 24;
export const DIGEST_RUN_THRESHOLD = 100;
export const DIGEST_BATCH_LIMIT = 200;
export const DIGEST_STATUS_DIGEST_LIMIT = 5;

export interface MemoryDigestStatus {
	project: string;
	totalEventCount: number;
	undigestedEventCount: number;
	digestibleEventCount: number;
	eligibleEventCount: number;
	batchEventCount: number;
	excludedRecentTail: number;
	minEventAgeHours: number;
	runThreshold: number;
	batchLimit: number;
	shouldRun: boolean;
	latestDigest?: string;
	latestCompleteThrough?: string;
	oldestEligibleEvent?: string;
	newestEligibleEvent?: string;
	recentDigests: string[];
	invalidRecentDigests: string[];
}

export interface MemoryDigestRunResult {
	path: string;
	statusBefore: MemoryDigestStatus;
	completeThrough: string;
	sourceEventCount: number;
	sourceHash: string;
}

type EventEntry = {
	file: string;
	path: string;
	relativePath: string;
	mtimeMs: number;
};

type DigestEntry = {
	file: string;
	path: string;
	relativePath: string;
	content?: string;
	completeThrough?: string;
};

export async function getMemoryDigestStatus(state: MemoryState): Promise<MemoryDigestStatus> {
	const events = await eventEntriesByFilename(state.paths);
	const recentDigests = await recentDigestEntries(state.paths);
	const latestDigest = recentDigests.find((digest) => digest.completeThrough);
	const completeThrough = latestDigest?.completeThrough;
	const completeThroughFile = completeThrough ? basename(completeThrough) : undefined;
	const undigested = completeThroughFile ? events.filter((event) => compareSortableFilenames(event.file, completeThroughFile) > 0) : events;
	const digestible = undigested.slice(0, Math.max(0, undigested.length - DIGEST_RECENT_EVENT_TAIL));
	const ageCutoff = Date.now() - DIGEST_MIN_EVENT_AGE_HOURS * 3_600_000;
	const eligible = digestible.filter((event) => event.mtimeMs <= ageCutoff);
	const batch = eligible.slice(0, DIGEST_BATCH_LIMIT);

	return {
		project: state.paths.projectKey,
		totalEventCount: events.length,
		undigestedEventCount: undigested.length,
		digestibleEventCount: digestible.length,
		eligibleEventCount: eligible.length,
		batchEventCount: batch.length,
		excludedRecentTail: Math.min(DIGEST_RECENT_EVENT_TAIL, undigested.length),
		minEventAgeHours: DIGEST_MIN_EVENT_AGE_HOURS,
		runThreshold: DIGEST_RUN_THRESHOLD,
		batchLimit: DIGEST_BATCH_LIMIT,
		shouldRun: eligible.length >= DIGEST_RUN_THRESHOLD,
		latestDigest: latestDigest?.relativePath,
		latestCompleteThrough: completeThrough,
		oldestEligibleEvent: eligible[0]?.relativePath,
		newestEligibleEvent: eligible[eligible.length - 1]?.relativePath,
		recentDigests: recentDigests.map((digest) => digest.relativePath),
		invalidRecentDigests: recentDigests.filter((digest) => !digest.completeThrough).map((digest) => digest.relativePath),
	};
}

export function formatMemoryDigestStatus(status: MemoryDigestStatus): string {
	return [
		`Memory digest status for ${status.project}`,
		`- Latest digest: ${status.latestDigest ?? "None."}`,
		`- Complete through event: ${status.latestCompleteThrough ?? "None."}`,
		`- Total raw events: ${status.totalEventCount}`,
		`- Undigested events after high-water: ${status.undigestedEventCount}`,
		`- Digestible after recent tail (${status.excludedRecentTail} excluded): ${status.digestibleEventCount}`,
		`- Eligible by age (${status.minEventAgeHours}h): ${status.eligibleEventCount}`,
		`- Next batch size: ${status.batchEventCount}`,
		`- Run threshold: ${status.runThreshold}`,
		`- Recommendation: ${status.shouldRun ? "run /memory-digest run" : "no digest needed yet"}`,
		status.oldestEligibleEvent ? `- Eligible range: ${status.oldestEligibleEvent} through ${status.newestEligibleEvent}` : undefined,
		status.invalidRecentDigests.length ? `- Invalid recent digests: ${status.invalidRecentDigests.join(", ")}` : undefined,
	].filter((line): line is string => Boolean(line)).join("\n");
}

export async function createMemoryDigest(state: MemoryState): Promise<MemoryDigestRunResult> {
	return createMemoryDigestAttempt(state, false);
}

async function createMemoryDigestAttempt(state: MemoryState, retried: boolean): Promise<MemoryDigestRunResult> {
	if (!state.dashboard?.trimStart().startsWith(MEMORY_LAYOUT_MARKER)) {
		throw new Error("Memory digest refused because the session/events layout marker is missing. Run /memory-migrate first.");
	}

	const statusBefore = await getMemoryDigestStatus(state);
	if (!statusBefore.shouldRun) {
		throw new Error(`Memory digest not needed yet: ${statusBefore.eligibleEventCount} eligible events, threshold is ${DIGEST_RUN_THRESHOLD}.`);
	}

	const events = await eventEntriesByFilename(state.paths);
	const completeThroughFile = statusBefore.latestCompleteThrough ? basename(statusBefore.latestCompleteThrough) : undefined;
	const undigested = completeThroughFile ? events.filter((event) => compareSortableFilenames(event.file, completeThroughFile) > 0) : events;
	const digestible = undigested.slice(0, Math.max(0, undigested.length - DIGEST_RECENT_EVENT_TAIL));
	const ageCutoff = Date.now() - DIGEST_MIN_EVENT_AGE_HOURS * 3_600_000;
	const sourceEvents = digestible.filter((event) => event.mtimeMs <= ageCutoff).slice(0, DIGEST_BATCH_LIMIT);
	if (!sourceEvents.length) throw new Error("Memory digest found no eligible source events after recomputing status.");

	const loaded = [] as Array<EventEntry & { content: string; hash: string }>;
	for (const event of sourceEvents) {
		const content = await readOptional(event.path);
		if (content === undefined) throw new Error(`Memory digest source event disappeared before it could be read: ${event.relativePath}`);
		loaded.push({ ...event, content, hash: hashContent(content) });
	}

	const statusAfterRead = await getMemoryDigestStatus(state);
	if (statusAfterRead.latestCompleteThrough !== statusBefore.latestCompleteThrough) {
		if (retried) throw new Error("Memory digest high-water changed during digest creation. Re-run /memory-digest run.");
		return createMemoryDigestAttempt(state, true);
	}

	const completeThrough = loaded[loaded.length - 1]?.relativePath;
	if (!completeThrough) throw new Error("Memory digest could not determine a complete-through event.");
	const sourceHash = hashContent(loaded.map((event) => `${event.relativePath} ${event.hash}`).join("\n"));
	const sourceHashShort = createHash("sha256").update(sourceHash, "utf8").digest("hex").slice(0, 12);
	const completeStem = parse(basename(completeThrough)).name;
	const digestFile = `${completeStem}-digest-${loaded.length}-${sourceHashShort}.md`;
	const digestPath = join(state.paths.eventDigestsDir, digestFile);
	const content = renderDigest(state, loaded, statusBefore, sourceHash);
	try {
		const path = await writeExclusiveFile(digestPath, content);
		return { path, statusBefore, completeThrough, sourceEventCount: loaded.length, sourceHash };
	} catch (error) {
		if (!isNodeErrorCode(error, "EEXIST")) throw error;
		return { path: digestPath, statusBefore, completeThrough, sourceEventCount: loaded.length, sourceHash };
	}
}

function renderDigest(state: MemoryState, events: Array<EventEntry & { content: string; hash: string }>, status: MemoryDigestStatus, sourceHash: string): string {
	const now = new Date().toISOString();
	const completeThrough = events[events.length - 1]?.relativePath ?? "None.";
	const kindCounts = new Map<string, number>();
	const sessionCounts = new Map<string, number>();
	const sources: MemorySource[] = [];
	for (const event of events) {
		const metadata = parseMemoryEventMetadata(event.content);
		const kind = metadata.kind ?? "event";
		kindCounts.set(kind, (kindCounts.get(kind) ?? 0) + 1);
		sessionCounts.set(metadata.sessionId ?? "unknown", (sessionCounts.get(metadata.sessionId ?? "unknown") ?? 0) + 1);
		sources.push({ kind: "event", path: event.relativePath, content: event.content, event: metadata });
	}
	const candidates = extractMemoryCandidates(sources, 12);
	const sourceLines = events.map((event) => `- ${event.relativePath} — ${event.hash}`);
	const previousDigest = status.latestDigest ?? "None.";
	return `# Memory Event Digest

Event metadata: v1
Kind: event-digest
Created: ${now}
Session ID: ${state.session.id}
Project: ${state.paths.projectKey}
Previous digest: ${previousDigest}
Complete through event: ${completeThrough}
Covers events before: ${new Date(Date.now() - DIGEST_MIN_EVENT_AGE_HOURS * 3_600_000).toISOString()}
Excludes newest event tail: ${DIGEST_RECENT_EVENT_TAIL}
Source event count: ${events.length}
Source hash: ${sourceHash}

## Source events
${sourceLines.join("\n")}

## Summary
- Digest covers ${events.length} immutable raw event files, ordered by sortable event filename.
- Raw events were not edited, moved, deleted, or marked.
- High-water is ${completeThrough}.

## Sessions
${formatCounts(sessionCounts)}

## Kinds
${formatCounts(kindCounts)}

## Durable candidates
${candidates.length ? candidates.map((candidate) => `- ${candidate.text} (source: ${candidate.sources.join(", ")})`).join("\n") : "- None."}

## Audit note
Raw events are immutable and remain authoritative. This digest is an additive summary only.

## Memory refs
- None.
`;
}

async function eventEntriesByFilename(paths: MemoryPaths): Promise<EventEntry[]> {
	try {
		const entries: EventEntry[] = [];
		for (const file of (await readdir(paths.eventsDir)).filter((entry) => entry.endsWith(".md")).sort(compareSortableFilenames)) {
			const path = join(paths.eventsDir, file);
			const info = await stat(path);
			if (info.isFile()) entries.push({ file, path, relativePath: relativeFrom(paths.projectDir, path), mtimeMs: info.mtimeMs });
		}
		return entries;
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

async function recentDigestEntries(paths: MemoryPaths): Promise<DigestEntry[]> {
	try {
		const entries = (await readdir(paths.eventDigestsDir))
			.filter((entry) => entry.endsWith(".md"))
			.sort((a, b) => compareSortableFilenames(b, a))
			.slice(0, DIGEST_STATUS_DIGEST_LIMIT);
		const digests: DigestEntry[] = [];
		for (const file of entries) {
			const path = join(paths.eventDigestsDir, file);
			const content = await readOptional(path);
			digests.push({ file, path, relativePath: relativeFrom(paths.projectDir, path), content, completeThrough: parseCompleteThrough(content) });
		}
		return digests;
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

function parseCompleteThrough(content: string | undefined): string | undefined {
	const value = content?.match(/^Complete through event:\s*(.+)$/im)?.[1]?.trim();
	return value && !/^None\.?$/i.test(value) ? value : undefined;
}

function compareSortableFilenames(a: string, b: string): number {
	return sortableFilenameKey(a).localeCompare(sortableFilenameKey(b));
}

function sortableFilenameKey(file: string): string {
	const name = basename(file);
	const timestamp = name.match(/^(\d{8}T\d{6}Z)-/)?.[1];
	return `${timestamp ?? "99999999T999999Z"}-${name}`;
}

function formatCounts(counts: Map<string, number>): string {
	const lines = [...counts.entries()]
		.sort(([left], [right]) => left.localeCompare(right))
		.map(([name, count]) => `- ${name}: ${count}`);
	return lines.length ? lines.join("\n") : "- None.";
}

function isNodeErrorCode(error: unknown, code: string): boolean {
	return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

import { truncateToWidth } from "@earendil-works/pi-tui";
import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import type { MemoryState } from "./memory.ts";
import type { TodoItem } from "./todo.ts";

const WIDGET_KEY = "pi-memory-workbench";
const MAX_WIDGET_LINES = 10;
const FALLBACK_WIDGET_WIDTH = 120;

type ThemeLike = {
	fg(color: "accent" | "dim" | "muted" | "success" | "text" | "warning", text: string): string;
	strikethrough?(text: string): string;
};

export class MemoryTodoWidget {
	private activeTodoKey = "";
	private completedItemKeysPendingHide = new Set<string>();
	private hiddenCompletedItemKeys = new Set<string>();
	private lastCurrent: MemoryState | undefined;
	private lastCtx: ExtensionContext | undefined;

	update(ctx: ExtensionContext, current: MemoryState): void {
		if (!ctx.hasUI) return;
		this.lastCtx = ctx;
		this.lastCurrent = current;

		const nextKey = current.activeTodoPath ?? current.parsedTodo?.title ?? "";
		if (nextKey !== this.activeTodoKey) {
			this.activeTodoKey = nextKey;
			this.resetCompletedDisplayState();
		}

		const lines = this.renderWidget(ctx.ui.theme, current, FALLBACK_WIDGET_WIDTH);
		ctx.ui.setWidget(WIDGET_KEY, lines.length > 0 ? lines : undefined, { placement: "aboveEditor" });
	}

	clear(ctx?: ExtensionContext): void {
		const target = ctx?.hasUI ? ctx : this.lastCtx;
		target?.ui.setWidget(WIDGET_KEY, undefined);
	}

	dispose(ctx?: ExtensionContext): void {
		this.clear(ctx);
		this.lastCtx = undefined;
		this.lastCurrent = undefined;
		this.activeTodoKey = "";
		this.resetCompletedDisplayState();
	}

	resetCompletedDisplayState(): void {
		this.completedItemKeysPendingHide.clear();
		this.hiddenCompletedItemKeys.clear();
	}

	hideCompletedTasksFromPreviousTurn(): void {
		if (this.completedItemKeysPendingHide.size === 0) return;
		for (const key of this.completedItemKeysPendingHide) this.hiddenCompletedItemKeys.add(key);
		this.completedItemKeysPendingHide.clear();
		if (this.lastCtx?.hasUI && this.lastCurrent) this.update(this.lastCtx, this.lastCurrent);
	}

	private visibleItems(current: MemoryState): TodoItem[] {
		const items = current.parsedTodo?.items ?? [];
		const hasActive = items.some((item) => item.status !== "done");
		if (!hasActive) return items;
		return items.filter((item) => item.status !== "done" || !this.hiddenCompletedItemKeys.has(this.itemKey(current, item)));
	}

	private renderWidget(theme: ThemeLike, current: MemoryState, width: number): string[] {
		if (!current.parsedTodo) return [];

		const counts = countItems(current.parsedTodo.items);
		if (counts.todo + counts.doing + counts.done + counts.blocked === 0) return [];

		const items = this.visibleItems(current);
		const active = counts.doing + counts.blocked + counts.todo > 0;
		const parts = [];
		if (counts.done) parts.push(`${counts.done} done`);
		if (counts.doing) parts.push(`${counts.doing} doing`);
		if (counts.blocked) parts.push(`${counts.blocked} blocked`);
		if (counts.todo) parts.push(`${counts.todo} open`);
		const tint = active ? "accent" : "dim";
		const lines = [this.truncate(theme.fg(tint, `${active ? "●" : "○"} ${current.parsedTodo.title} (${parts.join(", ") || "0 open"})`), width)];

		const ordered = [
			...items.filter((item) => item.status === "doing"),
			...items.filter((item) => item.status === "blocked"),
			...items.filter((item) => item.status === "todo"),
			...items.filter((item) => item.status === "done"),
		];

		const bodyBudget = MAX_WIDGET_LINES - 1;
		const needsSummary = ordered.length > bodyBudget;
		const visible = needsSummary ? ordered.slice(0, Math.max(0, bodyBudget - 1)) : ordered.slice(0, bodyBudget);

		for (const item of visible) lines.push(this.truncate(this.formatItem(theme, current, item), width));
		if (needsSummary) lines.push(this.truncate(theme.fg("dim", `  … ${ordered.length - visible.length} more completed`), width));
		for (const item of visible) {
			if (item.status === "done") this.completedItemKeysPendingHide.add(this.itemKey(current, item));
		}
		return lines;
	}

	private formatItem(theme: ThemeLike, current: MemoryState, item: TodoItem): string {
		const id = theme.fg("dim", `#${item.index}`);
		if (item.status === "doing") return `  ${theme.fg("warning", "◼")} ${id} ${theme.fg("accent", item.text)}`;
		if (item.status === "blocked") return `  ${theme.fg("warning", "!")} ${id} ${theme.fg("warning", item.text)}`;
		if (item.status === "done") {
			const text = theme.strikethrough ? theme.strikethrough(`${id} ${item.text}`) : `${id} ${item.text}`;
			this.completedItemKeysPendingHide.add(this.itemKey(current, item));
			return `  ${theme.fg("success", "✔")} ${theme.fg("dim", text)}`;
		}
		return `  ${theme.fg("muted", "◻")} ${id} ${theme.fg("text", item.text)}`;
	}

	private itemKey(current: MemoryState, item: TodoItem): string {
		return `${current.activeTodoPath ?? current.parsedTodo?.title ?? "todo"}:${item.index}:${item.text}`;
	}

	private truncate(line: string, width: number): string {
		return truncateToWidth(line, Math.max(1, width), "…");
	}
}

function countItems(items: TodoItem[]): Record<"todo" | "doing" | "done" | "blocked", number> {
	return {
		todo: items.filter((item) => item.status === "todo").length,
		doing: items.filter((item) => item.status === "doing").length,
		done: items.filter((item) => item.status === "done").length,
		blocked: items.filter((item) => item.status === "blocked").length,
	};
}

