export function parseProjectMemorySchema(content: string | undefined): ParsedProjectMemory {
	if (!content?.trim()) {
		return { isSchemaV1: false, entries: [], sections: new Map() };
	}

	const hasSchemaEnvelope = hasValidMemorySchemaEnvelope(content);
	const sections = new Map<string, string[]>();
	let currentSection = "";
	let inFence = false;
	for (const line of content.split(/\r?\n/)) {
		if (/^```/.test(line.trim())) {
			if (currentSection) sections.get(currentSection)?.push(line);
			inFence = !inFence;
			continue;
		}
		const heading = !inFence ? line.match(/^##\s+(.+?)\s*$/) : undefined;
		if (heading?.[1]) {
			currentSection = heading[1].trim();
			if (!sections.has(currentSection)) sections.set(currentSection, []);
			continue;
		}
		if (currentSection) sections.get(currentSection)?.push(line);
	}

	const isSchemaV1 = hasSchemaEnvelope && MEMORY_SCHEMA_SECTIONS.every((section) => sections.has(section));
	const entries: ParsedMemoryEntry[] = [];
	for (const [section, lines] of sections) {
		if (isSchemaV1 && !isMemorySchemaSection(section)) continue;
		for (const line of stripFencedLines(lines)) {
			const match = line.match(/^\s*[-*]\s+(.+)$/);
			if (!match?.[1]) continue;
			const text = entryText(match[1]);
			const normalized = normalizeMemoryText(text);
			if (!normalized) continue;
			entries.push({ section, id: entryId(match[1]), text, normalized, raw: line, status: entryStatus(line), supersededBy: supersededById(line) });
		}
	}

	if (!isSchemaV1) {
		for (const line of stripFencedLines(content.split(/\r?\n/))) {
			const match = line.match(/^\s*[-*]\s+(.+)$/);
			if (!match?.[1]) continue;
			const text = entryText(match[1]);
			const normalized = normalizeMemoryText(text);
			if (!normalized || entries.some((entry) => entry.normalized === normalized)) continue;
			entries.push({ section: "Legacy Memory", id: entryId(match[1]), text, normalized, raw: line, status: entryStatus(line), supersededBy: supersededById(line) });
		}
	}

	return { isSchemaV1, entries, sections, legacyContent: isSchemaV1 ? undefined : content.trim() };
}

export function extractMemoryCandidates(sources: MemorySource[], limit = 18): MemoryCandidate[] {
	const byText = new Map<string, MemoryCandidate>();
	for (const source of sources) {
		for (const line of sourceLines(source)) {
			const directive = supersedesDirective(line.text);
			const text = cleanCandidateText(directive?.text ?? line.text);
			if (isIncidentalCandidate(text) || (!line.section && !directive && !isPotentialMemoryCandidate(text))) continue;
			const candidate = classifyCandidate(text, source.path, line.section);
			if (directive) candidate.supersedes = directive.id;
			const key = normalizeMemoryText(candidate.text);
			if (!key) continue;
			const existing = byText.get(key);
			if (existing) {
				for (const path of candidate.sources) if (!existing.sources.includes(path)) existing.sources.push(path);
				if (candidate.supersedes && !existing.supersedes) existing.supersedes = candidate.supersedes;
				if (existing.section !== "Deferred" && candidate.section === "Deferred") {
					existing.section = "Deferred";
					existing.reason = candidate.reason;
				}
				continue;
			}
			byText.set(key, candidate);
			if (byText.size >= limit) return [...byText.values()];
		}
	}
	return [...byText.values()];
}

export async function applyDreamMemoryCandidates(params: {
	paths: MemoryPaths;
	expected: FileSnapshot;
	candidates: MemoryCandidate[];
	now: string;
}): Promise<DreamMemoryApplyResult> {
	let expected = params.expected;
	for (let attempt = 0; attempt < 2; attempt += 1) {
		let attemptResult: DreamMemoryApplyResult | undefined;
		try {
			await mutateFileIfUnchanged(params.paths.memoryPath, expected, (current) => {
				const memory = renderMemoryUpdate(current, params.candidates, params.now);
				attemptResult = {
					...memory.result,
					memoryHashBefore: current ? hashContent(current) : null,
					memoryHashAfter: hashContent(memory.content),
				};
				return memory.content;
			});
			if (!attemptResult) throw new Error("Dream memory update did not produce a result");
			return attemptResult;
		} catch (error) {
			if (attempt === 1 || !(error instanceof Error) || !error.message.startsWith("Memory conflict")) throw error;
			expected = await fileSnapshot(params.paths.memoryPath);
		}
	}
	throw new Error("Dream memory update retry failed");
}

function renderMemoryUpdate(current: string, candidates: MemoryCandidate[], now: string): { content: string; result: Omit<DreamMemoryApplyResult, "memoryHashBefore" | "memoryHashAfter"> } {
	const parsed = parseProjectMemorySchema(current);
	const date = now.slice(0, 10);
	const linesBySection = new Map<string, string[]>();
	const legacyPreserved = Boolean(current.trim() && !parsed.isSchemaV1);

	for (const section of MEMORY_SCHEMA_SECTIONS) linesBySection.set(section, []);
	if (parsed.isSchemaV1) {
		for (const [section, lines] of parsed.sections) linesBySection.set(section, [...lines]);
	} else if (legacyPreserved && parsed.legacyContent) {
		linesBySection.set("Legacy Memory", fencedLegacyContent(parsed.legacyContent));
	}

	const existingByNormalized = new Map<string, ParsedMemoryEntry>();
	const entriesById = new Map<string, ParsedMemoryEntry>();
	for (const entry of parsed.entries) {
		if (!existingByNormalized.has(entry.normalized)) existingByNormalized.set(entry.normalized, entry);
		if (entry.id) entriesById.set(entry.id, entry);
	}

	const applied: DreamMemoryEntryResult[] = [];
	const skippedDuplicates: Array<{ text: string; existingId?: string; sources: string[] }> = [];
	const deferred: DreamMemoryEntryResult[] = [];
	const superseded: Array<{ section: MemorySection; id: string; text: string; supersededBy: string; sources: string[] }> = [];
	const seenThisRun = new Set<string>();

	for (const candidate of candidates) {
		const normalized = normalizeMemoryText(candidate.text);
		if (!normalized || seenThisRun.has(normalized)) continue;
		seenThisRun.add(normalized);

		let section = candidate.section;
		let reason = candidate.reason;
		let target: ParsedMemoryEntry | undefined;
		if (candidate.supersedes) {
			target = entriesById.get(candidate.supersedes);
			if (!target) {
				section = "Deferred";
				reason = `supersedes unknown memory id ${candidate.supersedes}`;
			} else if (!isMemorySchemaSection(target.section) || target.section === "Deferred") {
				section = "Deferred";
				reason = `cannot supersede ${candidate.supersedes} from ${target.section}`;
			} else if (target.normalized === normalized) {
				section = "Deferred";
				reason = `replacement is identical to ${candidate.supersedes}`;
			} else if (section === "Deferred" && reason === "low-confidence candidate needs manual review") {
				section = target.section;
				reason = undefined;
			}
		}

		const existing = existingByNormalized.get(normalized);
		if (target?.status === "superseded") {
			if (existing?.id && existing.id === target.supersededBy) {
				skippedDuplicates.push({ text: candidate.text, existingId: existing.id, sources: candidate.sources });
				continue;
			}
			section = "Deferred";
			reason = `memory id ${target.id} is already superseded by ${target.supersededBy ?? "an unknown entry"}`;
		}

		if (existing) {
			skippedDuplicates.push({ text: candidate.text, existingId: existing.id, sources: candidate.sources });
			if (target?.id && target.status !== "superseded" && section !== "Deferred" && existing.id && existing.section !== "Deferred" && existing.status === "active" && supersedeMemoryEntry(linesBySection, target, existing.id, date)) {
				target.status = "superseded";
				target.supersededBy = existing.id;
				superseded.push({ section: target.section as MemorySection, id: target.id, text: target.text, supersededBy: existing.id, sources: candidate.sources });
			}
			continue;
		}

		const contradictionEntries = [...parsed.entries, ...applied.map((entry): ParsedMemoryEntry => ({
			section: entry.section,
			id: entry.id,
			text: entry.text,
			normalized: normalizeMemoryText(entry.text),
			raw: entry.text,
			status: "active",
		}))].filter((entry) => entry.status === "active" && entry.id !== target?.id);
		const contradiction = section === "Deferred" ? undefined : findContradiction(candidate.text, contradictionEntries);
		if (contradiction) {
			section = "Deferred";
			reason = contradiction;
		}
		const id = stableMemoryId(section, candidate.text);
		const entry = {
			section,
			id,
			text: candidate.text,
			ref: `memory.md#${sectionAnchor(section)}`,
			sources: candidate.sources,
			reason,
		};
		const line = section === "Deferred"
			? `- [id: ${id}] ${candidate.text} (deferred: ${reason ?? "manual review required"}; source: ${candidate.sources.join(", ")}; seen: ${date})`
			: `- [id: ${id}] ${candidate.text} (source: ${candidate.sources.join(", ")}; seen: ${date})`;
		const sectionLines = linesBySection.get(section) ?? [];
		if (sectionLines.length && sectionLines[sectionLines.length - 1]?.trim()) sectionLines.push("");
		sectionLines.push(line);
		linesBySection.set(section, sectionLines);
		const parsedEntry: ParsedMemoryEntry = { section, id, text: candidate.text, normalized, raw: line, status: "active" };
		existingByNormalized.set(normalized, parsedEntry);
		entriesById.set(id, parsedEntry);
		if (section === "Deferred") {
			deferred.push(entry);
		} else {
			applied.push(entry);
			if (target?.id && target.status !== "superseded" && supersedeMemoryEntry(linesBySection, target, id, date)) {
				target.status = "superseded";
				target.supersededBy = id;
				superseded.push({ section: target.section as MemorySection, id: target.id, text: target.text, supersededBy: id, sources: candidate.sources });
			}
		}
	}

	return {
		content: renderSchemaMemory(linesBySection),
		result: { applied, skippedDuplicates, deferred, superseded, legacyPreserved },
	};
}

function isMemorySchemaSection(section: string): section is MemorySection {
	return (MEMORY_SCHEMA_SECTIONS as readonly string[]).includes(section);
}

function hasValidMemorySchemaEnvelope(content: string): boolean {
	const lines = content.split(/\r?\n/);
	const firstSection = lines.findIndex((line) => /^##\s+/.test(line));
	if (firstSection < 0) return false;
	const header = lines.slice(0, firstSection).map((line) => line.trim()).filter(Boolean);
	return header.length === 3
		&& header[0] === "# Project Memory"
		&& header[1] === MEMORY_SCHEMA_MARKER
		&& header[2] === MEMORY_SCHEMA_DESCRIPTION;
}

function stripFencedLines(lines: string[]): string[] {
	const result: string[] = [];
	let inFence = false;
	for (const line of lines) {
		if (/^```/.test(line.trim())) {
			inFence = !inFence;
			continue;
		}
		if (!inFence) result.push(line);
	}
	return result;
}

function renderSchemaMemory(linesBySection: Map<string, string[]>): string {
	const output = [
		"# Project Memory",
		MEMORY_SCHEMA_MARKER,
		"",
		MEMORY_SCHEMA_DESCRIPTION,
	];
	for (const section of MEMORY_SCHEMA_SECTIONS) {
		output.push("", `## ${section}`);
		const lines = trimBlankEdges(linesBySection.get(section) ?? []);
		if (lines.length) output.push(...lines);
	}
	const legacy = trimBlankEdges(linesBySection.get("Legacy Memory") ?? []);
	if (legacy.length) output.push("", "## Legacy Memory", ...legacy);
	for (const [section, lines] of linesBySection) {
		if (MEMORY_SCHEMA_SECTIONS.includes(section as MemorySection) || section === "Legacy Memory") continue;
		const extra = trimBlankEdges(lines);
		if (extra.length) output.push("", `## ${section}`, ...extra);
	}
	return `${output.join("\n").trimEnd()}\n`;
}

type MemoryCandidateLine = {
	text: string;
	section?: Exclude<MemorySection, "Deferred">;
};

function sourceLines(source: MemorySource): MemoryCandidateLine[] {
	if (source.kind === "memory") return [];
	if (source.kind === "event-digest") return sectionLines(source.content, "Durable candidates");
	if (source.kind === "session-progress") {
		const resume = extractSection(source.content, "Resume Here");
		const verification = resume?.split(/\r?\n/).find((line) => /^\s*-\s*Last verified command:\s*(?!Not recorded\.?\s*$).+/i.test(line));
		return [...sectionLines(source.content, "Updates"), ...(verification ? [{ text: verification }] : [])];
	}
	if (source.kind === "session-todo" || source.kind === "legacy-todo") return sectionLines(source.content, "Notes");
	return [
		...sectionLines(source.content, "Conventions", "Conventions"),
		...sectionLines(source.content, "Decisions", "Decisions"),
		...sectionLines(source.content, "Verified Commands", "Verified Commands"),
		...sectionLines(source.content, "Gotchas", "Gotchas"),
		...sectionLines(source.content, "Avoid", "Avoid"),
		...sectionLines(source.content, "Durable Facts"),
		...sectionLines(source.content, "Summary"),
	];
}

function sectionLines(content: string, heading: string, section?: Exclude<MemorySection, "Deferred">): MemoryCandidateLine[] {
	const value = extractSection(content, heading);
	return value ? value.split(/\r?\n/).map((text) => section ? { text, section } : { text }) : [];
}

function classifyCandidate(text: string, sourcePath: string, section?: Exclude<MemorySection, "Deferred">): MemoryCandidate {
	const risk = highRiskReason(text);
	if (risk) return { text, section: "Deferred", sources: [sourcePath], reason: risk };
	if (section) return { text, section, sources: [sourcePath] };
	if (!isProjectLocalText(text)) return { text, section: "Deferred", sources: [sourcePath], reason: "not clearly project-local" };
	if (/\b(verified|validation|smoke|passed|last verified command)\b/i.test(text) && (/`[^`]+`/.test(text) || /\b(?:node|npm|pnpm|yarn|bun|tsc|pytest|go test|cargo|deno)\b/i.test(text))) {
		return { text, section: "Verified Commands", sources: [sourcePath] };
	}
	if (/\b(avoid|do not|don't|never|forbidden|deprecated|failed approach|must not)\b/i.test(text)) return { text, section: "Avoid", sources: [sourcePath] };
	if (/\b(gotcha|caveat|blocker|failure mode|edge case|pitfall|risk)\b/i.test(text)) return { text, section: "Gotchas", sources: [sourcePath] };
	if (/\b(decision|decided|agreed|chose|chosen|approved|hard cutover|source of truth)\b/i.test(text)) return { text, section: "Decisions", sources: [sourcePath] };
	if (/\b(convention|pattern|layout|generated|authoritative|prefer|use|writes? to|reads? from|lives under)\b/i.test(text)) return { text, section: "Conventions", sources: [sourcePath] };
	return { text, section: "Deferred", sources: [sourcePath], reason: "low-confidence candidate needs manual review" };
}

function highRiskReason(text: string): string | undefined {
	if (/\b(global\.md|global memory|cross-project|user preference|personal preference)\b/i.test(text)) return "global preference or global memory change";
	if (/\bAGENTS\.md\b/i.test(text)) return "AGENTS.md policy change requires manual review";
	if (/\b(api[_-]?key|access[_-]?token|auth[_-]?token|bearer token|refresh token|secret|credential|password|private key)\b/i.test(text)) return "possible secret or credential";
	if (/\b(maybe|possibly|probably|speculative|uncertain|unknown|unresolved|open question|needs decision|blocked on decision)\b/i.test(text)) return "speculative or unresolved";
	if (/\b(product decision|architecture decision)\b/i.test(text) && /\b(unresolved|pending|needs|ask|question)\b/i.test(text)) return "unresolved product or architecture decision";
	if (/\b(failed|failure)\b/i.test(text) && !/\b(avoid|do not|never|gotcha|failure mode|durable|lesson)\b/i.test(text)) return "one-off failure without a durable lesson";
	return undefined;
}

function isProjectLocalText(text: string): boolean {
	return /\b(pi-memory-workbench|memory\.md|progress\.md|todo\.md|events?|event-digests?|dreams?|sessions?|dashboard|repo|extension|layout|schema-v1|metadata-v1)\b/i.test(text)
		|| /`[^`]+`/.test(text)
		|| /\b[\w.-]+\.(?:ts|js|json|md|yml|yaml)\b/i.test(text);
}

function findContradiction(candidate: string, existing: ParsedMemoryEntry[]): string | undefined {
	const candidateAnchors = anchors(candidate);
	if (!candidateAnchors.size) return undefined;
	const candidatePolarity = polarity(candidate);
	if (candidatePolarity === "neutral") return undefined;
	for (const entry of existing) {
		if (entry.section === "Deferred") continue;
		const entryPolarity = polarity(entry.text);
		if (entryPolarity === "neutral" || entryPolarity === candidatePolarity) continue;
		const shared = [...candidateAnchors].filter((anchor) => anchors(entry.text).has(anchor));
		if (shared.length) return `possible contradiction with ${entry.id ?? entry.section}`;
	}
	return undefined;
}

function anchors(text: string): Set<string> {
	const values = new Set<string>();
	for (const match of text.matchAll(/`([^`]+)`/g)) if (match[1]) values.add(match[1].toLowerCase());
	for (const match of text.matchAll(/\b(?:[\w.-]+\/)+[\w.-]+\b|\b[\w.-]+\.(?:md|ts|js|json|yml|yaml)\b/g)) values.add(match[0].toLowerCase());
	for (const match of text.matchAll(/\b(?:memory|progress|todo|dream|digest|dashboard|session|event)s?\b/gi)) values.add(match[0].toLowerCase());
	return values;
}

function polarity(text: string): "positive" | "negative" | "neutral" {
	const negative = /\b(avoid|do not|don't|never|forbidden|deprecated|failed|must not|refuse|disable|off|false)\b/i.test(text);
	const positive = /\b(use|prefer|must|should|verified|passed|enable|on|true|authoritative|source of truth)\b/i.test(text);
	if (negative && !positive) return "negative";
	if (positive && !negative) return "positive";
	return "neutral";
}

function stableMemoryId(section: MemorySection, text: string): string {
	return `${SECTION_PREFIX[section]}-${createHash("sha256").update(`${section}\n${normalizeMemoryText(text)}`, "utf8").digest("hex").slice(0, 8)}`;
}

function supersedesDirective(line: string): { id: string; text: string } | undefined {
	const match = line.match(/^\s*(?:[-*+]\s+)?\[supersedes:\s*([^\]]+)\]\s*(.+)$/i);
	const id = match?.[1]?.trim();
	const text = match?.[2]?.trim();
	return id && text ? { id, text } : undefined;
}

function cleanCandidateText(line: string): string {
	return line
		.replace(/^\s*[-*+]\s+/, "")
		.replace(/^\[[ x>!]\]\s+/i, "")
		.replace(/^\d+\.\s+/, "")
		.replace(/^\w[\w /-]*:\s+/, (prefix) => /^(current state|next action|current objective|last verified command|update|summary|decision|convention|avoid|gotcha|verified command)/i.test(prefix) ? prefix : "")
		.replace(/\s+/g, " ")
		.trim();
}

function isIncidentalCandidate(text: string): boolean {
	if (!text) return true;
	if (/^sha256:[a-f0-9]+$/i.test(text)) return true;
	return /^(?:\.{0,2}\/|\/)?(?:[\w.@-]+\/)*[\w.@-]+\.(?:md|ts|js|json|ya?ml)(?:\s+\([^)]*\))?(?::\s*sha256:[a-f0-9]+)?$/i.test(text);
}

function isPotentialMemoryCandidate(text: string): boolean {
	if (text.length < 18 || text.length > 500) return false;
	if (/^no (new )?(durable|event|todo|memory|source)/i.test(text)) return false;
	return /\b(decision|decided|convention|pattern|command|verified|passed|avoid|failed|failure|gotcha|caveat|blocker|edge case|prefer|generated|authoritative|source of truth|do not|don't|never|must|should|layout|digest|dream|memory\.md|progress\.md|todo\.md)\b/i.test(text);
}

function supersedeMemoryEntry(linesBySection: Map<string, string[]>, target: ParsedMemoryEntry, replacementId: string, date: string): boolean {
	if (!target.id || target.status === "superseded") return false;
	const lines = linesBySection.get(target.section);
	const index = lines?.findIndex((line) => line === target.raw) ?? -1;
	if (!lines || index < 0) return false;
	const lifecycle = `status: superseded; superseded-by: ${replacementId}; superseded: ${date}`;
	const line = lines[index] ?? target.raw;
	lines[index] = /\)\s*$/.test(line) ? line.replace(/\)\s*$/, `; ${lifecycle})`) : `${line} (${lifecycle})`;
	return true;
}

export function normalizeMemoryText(text: string): string {
	return entryText(text)
		.toLowerCase()
		.replace(/[“”]/g, "\"")
		.replace(/[‘’]/g, "'")
		.replace(/[`*_~]/g, "")
		.replace(/[.;:!?]+/g, "")
		.replace(/\s+/g, " ")
		.trim();
}

function entryText(text: string): string {
	return text
		.replace(/^\s*[-*]\s+/, "")
		.replace(/\[id:\s*[^\]]+\]\s*/i, "")
		.replace(/\s*\((?:source|sources|deferred):[^)]*\)\s*$/i, "")
		.trim();
}

function entryId(text: string): string | undefined {
	return text.match(/\[id:\s*([^\]]+)\]/i)?.[1]?.trim();
}

function entryStatus(text: string): "active" | "superseded" | "disputed" {
	const status = text.match(/(?:^|;\s*)status:\s*(active|superseded|disputed)(?:;|\))/i)?.[1]?.toLowerCase();
	return status === "superseded" || status === "disputed" ? status : "active";
}

function supersededById(text: string): string | undefined {
	return text.match(/(?:^|;\s*)superseded-by:\s*([^;)]+)(?:;|\))/i)?.[1]?.trim();
}

function sectionAnchor(section: string): string {
	return section.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

function fencedLegacyContent(content: string): string[] {
	return ["Original pre-schema memory.md preserved during schema-v1 migration.", "", "```md", content.replace(/```/g, "` ` `"), "```"];
}

function trimBlankEdges(lines: string[]): string[] {
	let start = 0;
	let end = lines.length;
	while (start < end && !lines[start]?.trim()) start += 1;
	while (end > start && !lines[end - 1]?.trim()) end -= 1;
	return lines.slice(start, end);
}

function extractSection(content: string, heading: string): string | undefined {
	const pattern = new RegExp(`^##\\s+${heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*$`, "im");
	const match = pattern.exec(content);
	if (!match) return undefined;
	const start = match.index + match[0].length;
	const rest = content.slice(start);
	const next = rest.search(/^##\s+/m);
	return (next >= 0 ? rest.slice(0, next) : rest).trim() || undefined;
}

import { access } from "node:fs/promises";
import { join } from "node:path";
import { parseMemoryEventMetadata, type MemoryEventMetadata } from "./memory-events.ts";
import { getMemoryDigestStatus, type MemoryDigestStatus } from "./memory-digest.ts";
import { MEMORY_SCHEMA_SECTIONS, parseProjectMemorySchema } from "./memory-schema.ts";
import { MEMORY_LAYOUT_MARKER, readOptional } from "./paths.ts";
import { parseTodo } from "./todo.ts";
import type { MemoryState } from "./memory.ts";

export type MemoryLintSeverity = "ok" | "info" | "warn" | "error";

export interface MemoryLintCheck {
	severity: MemoryLintSeverity;
	name: string;
	message: string;
	recommendation?: string;
}

export interface MemoryLintReport {
	project: string;
	checks: MemoryLintCheck[];
	recommendations: string[];
	digest: MemoryDigestStatus;
}

export async function lintMemory(state: MemoryState): Promise<MemoryLintReport> {
	const checks: MemoryLintCheck[] = [];
	checkDashboard(state, checks);
	checkSessionProgress(state, checks);
	checkSessionTodo(state, checks);
	checkLegacyTodo(state, checks);
	checkProjectMemory(state, checks);
	checkDreams(state, checks);
	await checkRecentEvents(state, checks);
	const digest = await getMemoryDigestStatus(state);
	checkDigest(state, digest, checks);
	return { project: state.paths.projectKey, checks, recommendations: uniqueRecommendations(checks), digest };
}

export function formatMemoryLintReport(report: MemoryLintReport): string {
	const counts = new Map<MemoryLintSeverity, number>([["error", 0], ["warn", 0], ["info", 0], ["ok", 0]]);
	for (const check of report.checks) counts.set(check.severity, (counts.get(check.severity) ?? 0) + 1);
	return [
		`Memory lint for ${report.project}`,
		`Status: ${counts.get("error")} error, ${counts.get("warn")} warn, ${counts.get("info")} info, ${counts.get("ok")} ok`,
		"",
		...report.checks.map((check) => `${prefix(check.severity)} ${check.name}: ${check.message}${check.recommendation ? ` Recommendation: ${check.recommendation}` : ""}`),
		report.recommendations.length ? "" : undefined,
		report.recommendations.length ? "Recommendations:" : undefined,
		...report.recommendations.map((recommendation) => `- ${recommendation}`),
	].filter((line): line is string => line !== undefined).join("\n");
}

function checkDashboard(state: MemoryState, checks: MemoryLintCheck[]): void {
	if (!state.dashboard?.trim()) {
		checks.push({ severity: "error", name: "dashboard layout", message: `${state.paths.progressPath} is missing.`, recommendation: writeRecommendation(state, "Run /memory-migrate to create the session/events dashboard.") });
		return;
	}
	if (!state.dashboard.trimStart().startsWith(MEMORY_LAYOUT_MARKER)) {
		checks.push({ severity: "error", name: "dashboard layout", message: "Shared progress.md does not have the session/events layout marker.", recommendation: writeRecommendation(state, "Run /memory-migrate for layout migration only.") });
		return;
	}
	checks.push({ severity: "ok", name: "dashboard layout", message: "Shared progress.md has the session/events layout marker." });
	if (/non-authoritative/i.test(state.dashboard) && /not the Resume Here source|Authoritative session state lives/i.test(state.dashboard)) {
		checks.push({ severity: "ok", name: "dashboard wording", message: "Dashboard states that it is non-authoritative." });
	} else {
		checks.push({ severity: "warn", name: "dashboard wording", message: "Dashboard marker exists, but dashboard-only wording is missing or unclear.", recommendation: writeRecommendation(state, "Run /memory-migrate to regenerate the dashboard wording.") });
	}
}

function checkSessionProgress(state: MemoryState, checks: MemoryLintCheck[]): void {
	if (state.session.memoryMode === "readonly") {
		checks.push({ severity: "info", name: "session progress", message: "Memory is read-only for this non-owner session; owner sessions own durable progress checkpoints." });
		return;
	}
	if (!state.progress?.trim()) {
		checks.push({ severity: "error", name: "session progress", message: `${state.paths.sessionProgressPath} is missing.`, recommendation: "Create a checkpoint with /memory-checkpoint or the memory_checkpoint tool." });
		return;
	}
	if (/^##\s+Resume Here\s*$/im.test(state.progress)) {
		checks.push({ severity: "ok", name: "session progress", message: "Current session progress has a Resume Here section." });
	} else {
		checks.push({ severity: "error", name: "session progress", message: "Current session progress is missing ## Resume Here.", recommendation: "Update the session checkpoint with /memory-checkpoint or the memory_checkpoint tool." });
	}
}

function checkSessionTodo(state: MemoryState, checks: MemoryLintCheck[]): void {
	if (state.session.memoryMode === "readonly") {
		checks.push({ severity: "info", name: "session todo", message: "Memory is read-only for this non-owner session; owner sessions own durable todo state." });
		return;
	}
	if (!state.activeTodo?.trim()) {
		checks.push({ severity: "info", name: "session todo", message: "No session todo exists yet." });
		return;
	}
	const parsed = parseTodo(state.activeTodo);
	checks.push({ severity: "ok", name: "session todo", message: `Parsed session todo "${parsed.title}" with ${parsed.items.length} item(s).` });
	if (!/^Session ID:/im.test(state.activeTodo) || !/^Session progress:/im.test(state.activeTodo)) {
		checks.push({ severity: "warn", name: "session todo metadata", message: "Session todo is missing session metadata lines.", recommendation: "Create new session todos with /todo-new; manually review imported legacy todos." });
	}
}

function checkLegacyTodo(state: MemoryState, checks: MemoryLintCheck[]): void {
	if (state.currentTodo?.trim()) {
		checks.push({ severity: "info", name: "legacy todo", message: "legacy todos/current.md exists and is migration-source-only; new commands should not update it." });
	} else {
		checks.push({ severity: "ok", name: "legacy todo", message: "No active legacy todos/current.md content found." });
	}
}

function checkProjectMemory(state: MemoryState, checks: MemoryLintCheck[]): void {
	const parsed = parseProjectMemorySchema(state.projectMemory);
	if (!state.projectMemory?.trim()) {
		checks.push({ severity: "warn", name: "project memory", message: "memory.md is missing.", recommendation: writeRecommendation(state, "Run /dream-run to create schema-v1 project memory when durable candidates exist.") });
		return;
	}
	if (!parsed.isSchemaV1) {
		checks.push({ severity: "warn", name: "project memory schema", message: "memory.md is freeform or legacy and lacks the schema-v1 marker.", recommendation: writeRecommendation(state, "Run /dream-run for conservative schema-v1 preservation, or manually review ambiguous legacy content.") });
		return;
	}
	checks.push({ severity: "ok", name: "project memory schema", message: "memory.md uses schema-v1." });
	if (parsed.sections.has("Legacy Memory")) {
		checks.push({ severity: "warn", name: "project memory legacy", message: "memory.md still contains preserved legacy content.", recommendation: "Manually review ## Legacy Memory and promote durable facts into schema sections when useful." });
	}
	for (const section of MEMORY_SCHEMA_SECTIONS) {
		if (!parsed.sections.has(section)) checks.push({ severity: "error", name: "project memory headings", message: `memory.md is missing ## ${section}.`, recommendation: writeRecommendation(state, "Run /dream-run or manually repair the schema-v1 headings.") });
	}
	const byNormalized = new Map<string, string[]>();
	for (const entry of parsed.entries) {
		const locations = byNormalized.get(entry.normalized) ?? [];
		locations.push(entry.id ? `${entry.section}:${entry.id}` : entry.section);
		byNormalized.set(entry.normalized, locations);
	}
	const duplicates = [...byNormalized.values()].filter((locations) => locations.length > 1);
	if (duplicates.length) {
		checks.push({ severity: "warn", name: "project memory duplicates", message: `${duplicates.length} duplicate normalized memory entr${duplicates.length === 1 ? "y" : "ies"} found.`, recommendation: "Manually review duplicate memory.md bullets." });
	} else {
		checks.push({ severity: "ok", name: "project memory duplicates", message: "No duplicate normalized memory entries found." });
	}
	const entriesById = new Map(parsed.entries.filter((entry) => entry.id).map((entry) => [entry.id as string, entry]));
	const invalidLifecycle = parsed.entries.filter((entry) => entry.status === "superseded" && (!entry.supersededBy || !entriesById.has(entry.supersededBy)));
	if (invalidLifecycle.length) {
		checks.push({ severity: "warn", name: "project memory lifecycle", message: `${invalidLifecycle.length} superseded memory entr${invalidLifecycle.length === 1 ? "y has" : "ies have"} a missing or unresolved superseded-by reference.`, recommendation: "Manually review memory.md lifecycle references; Dreams never delete superseded source entries." });
	} else {
		const superseded = parsed.entries.filter((entry) => entry.status === "superseded").length;
		checks.push({ severity: "ok", name: "project memory lifecycle", message: `${superseded} superseded memory entr${superseded === 1 ? "y" : "ies"}; all replacement references resolve.` });
	}
	const deferred = parsed.entries.filter((entry) => entry.section === "Deferred");
	const policyDeferred = deferred.filter((entry) => /AGENTS\.md|global\.md|global memory|secret|credential|contradiction|manual review|unresolved/i.test(entry.raw));
	if (policyDeferred.length) {
		checks.push({ severity: "warn", name: "project memory deferred", message: `${policyDeferred.length} deferred policy, contradiction, secret, or manual-review entr${policyDeferred.length === 1 ? "y" : "ies"} need review.`, recommendation: "Manually review memory.md ## Deferred entries." });
	} else {
		checks.push({ severity: "ok", name: "project memory deferred", message: "No high-risk deferred memory entries detected." });
	}
}

function checkDreams(state: MemoryState, checks: MemoryLintCheck[]): void {
	if (state.dream.state === "fresh") {
		checks.push({ severity: "ok", name: "dream freshness", message: `Dreams are fresh${state.dream.ageHours === undefined ? "" : ` (${state.dream.ageHours}h old)`}.` });
		return;
	}
	if (state.dream.state === "never") {
		checks.push({ severity: "warn", name: "dream freshness", message: "Dreams have never run.", recommendation: writeRecommendation(state, "Run /dream-run to curate schema-v1 memory.") });
		return;
	}
	checks.push({ severity: "warn", name: "dream freshness", message: `Dreams are stale${state.dream.ageHours === undefined ? "" : ` (${state.dream.ageHours}h old)`}.`, recommendation: writeRecommendation(state, "Run /dream-run.") });
}

async function checkRecentEvents(state: MemoryState, checks: MemoryLintCheck[]): Promise<void> {
	let legacyCount = 0;
	let v1Count = 0;
	let metadataProblems = 0;
	let relatedProblems = 0;
	for (const event of state.recentEvents) {
		const content = await readOptional(event.path);
		if (!content) continue;
		const metadata = parseMemoryEventMetadata(content);
		if (metadata.version !== "v1") {
			legacyCount += 1;
			continue;
		}
		v1Count += 1;
		if (missingRequiredEventFields(metadata).length) metadataProblems += 1;
		for (const ref of [metadata.relatedEvents.previousEvent, metadata.relatedEvents.previousSameSessionEvent, metadata.relatedEvents.previousSameKindEvent]) {
			if (ref && !(await pathExists(join(state.paths.projectDir, ref)))) relatedProblems += 1;
		}
	}
	if (legacyCount) checks.push({ severity: "info", name: "recent legacy events", message: `${legacyCount} recent legacy event(s) found; they are compatible immutable history and should not be backfilled.` });
	else checks.push({ severity: "ok", name: "recent legacy events", message: "No legacy metadata events found in the recent event window." });
	if (!v1Count) checks.push({ severity: "info", name: "recent event metadata", message: "No metadata-v1 events found in the recent event window." });
	else if (metadataProblems) checks.push({ severity: "error", name: "recent event metadata", message: `${metadataProblems} metadata-v1 event(s) are missing required fields.`, recommendation: "Inspect recent events manually; raw event files are immutable, so fix the writer for future events." });
	else checks.push({ severity: "ok", name: "recent event metadata", message: `${v1Count} metadata-v1 event(s) include required fields.` });
	if (relatedProblems) checks.push({ severity: "warn", name: "related event links", message: `${relatedProblems} related event link(s) do not resolve.`, recommendation: "Inspect recent events manually; raw event files are immutable, so fix the writer for future events." });
	else checks.push({ severity: "ok", name: "related event links", message: "Recent related event links resolve or are None." });
}

function checkDigest(state: MemoryState, digest: MemoryDigestStatus, checks: MemoryLintCheck[]): void {
	if (digest.invalidRecentDigests.length) {
		checks.push({ severity: "warn", name: "event digests", message: `${digest.invalidRecentDigests.length} recent digest(s) lack Complete through event metadata.`, recommendation: "Manually inspect event-digests/; raw events remain authoritative." });
	}
	if (digest.shouldRun) {
		checks.push({ severity: "warn", name: "event digests", message: `${digest.eligibleEventCount} old undigested event(s) are eligible for digesting.`, recommendation: writeRecommendation(state, "Run /memory-digest run.") });
	} else {
		checks.push({ severity: "ok", name: "event digests", message: `${digest.eligibleEventCount} old undigested event(s), below threshold ${digest.runThreshold}.` });
	}
}

function writeRecommendation(state: MemoryState, recommendation: string): string {
	if (state.session.memoryMode === "owner") return recommendation;
	const parentRecommendation = recommendation.replace(/^Run\s+/, "Ask the parent or owner session to run ");
	return `${parentRecommendation} Non-owner sessions use memory read-only.`;
}

function missingRequiredEventFields(metadata: MemoryEventMetadata): string[] {
	const missing: string[] = [];
	for (const label of ["Kind", "Created", "Session ID", "Actor kind", "Parent session", "Project", "Session progress", "Session todo", "Memory", "Source hash basis"]) {
		if (!metadata.labels.has(label)) missing.push(label);
	}
	for (const label of ["Source hashes", "Related events", "Memory refs", "Digest refs"]) {
		if (!metadata.listSections.has(label)) missing.push(label);
	}
	if (!metadata.kind) missing.push("Kind value");
	if (!metadata.created) missing.push("Created value");
	if (!metadata.sessionId) missing.push("Session ID value");
	if (!metadata.actorKind) missing.push("Actor kind value");
	if (!metadata.project) missing.push("Project value");
	if (!metadata.sessionProgress) missing.push("Session progress value");
	if (!metadata.sessionTodo) missing.push("Session todo value");
	if (!metadata.memory) missing.push("Memory value");
	if (!metadata.sourceHashBasis) missing.push("Source hash basis value");
	if (!metadata.sourceHashes.length) missing.push("Source hashes entries");
	for (const path of [metadata.sessionProgress, metadata.sessionTodo, "progress.md", metadata.memory?.replace(/\s+\(missing\)$/i, "")].filter((value): value is string => Boolean(value))) {
		if (!metadata.sourceHashes.some((source) => source.path === path)) missing.push(`Source hash for ${path}`);
	}
	return missing;
}

function uniqueRecommendations(checks: MemoryLintCheck[]): string[] {
	return [...new Set(checks.map((check) => check.recommendation).filter((value): value is string => Boolean(value)))];
}

function prefix(severity: MemoryLintSeverity): string {
	if (severity === "error") return "[error]";
	if (severity === "warn") return "[warn]";
	if (severity === "info") return "[info]";
	return "[ok]";
}

async function pathExists(path: string): Promise<boolean> {
	try {
		await access(path);
		return true;
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return false;
		throw error;
	}
}

function isNodeErrorCode(error: unknown, code: string): boolean {
	return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

import { readdir, realpath, stat } from "node:fs/promises";
import { basename, join, relative, resolve } from "node:path";
import { parseMemoryEventMetadata } from "./memory-events.ts";
import { readOptional, relativeFrom, type MemoryPaths } from "./paths.ts";
import type { MemoryState } from "./memory.ts";

export const MEMORY_RECALL_SCOPES = ["project", "session", "memory", "events", "dreams", "digests"] as const;
export type MemoryRecallScope = typeof MEMORY_RECALL_SCOPES[number];

export interface MemoryRecallOptions {
	query: string;
	scope?: MemoryRecallScope;
	sessionId?: string;
	kind?: string;
	limit?: number;
}

export interface MemoryRecallDocument {
	path: string;
	kind: string;
	content: string;
	title: string;
	sessionId?: string;
	created?: string;
}

export interface MemoryRecallHit {
	path: string;
	kind: string;
	title: string;
	sessionId?: string;
	created?: string;
	score: number;
	matchedTerms: string[];
	snippet: string;
}

export interface MemoryRecallResult {
	query: string;
	scope: MemoryRecallScope;
	totalDocuments: number;
	totalMatches: number;
	hits: MemoryRecallHit[];
}

const DEFAULT_LIMIT = 8;
const MAX_LIMIT = 20;
const MAX_QUERY_LENGTH = 256;
const MAX_EXPANDED_CHARS = 30_000;
const SNIPPET_CONTEXT_LINES = 1;
const STOPWORDS = new Set([
	"a", "an", "and", "are", "as", "at", "be", "been", "by", "did", "do", "does", "for", "from",
	"had", "has", "have", "how", "in", "is", "it", "its", "of", "on", "or", "that", "the", "their",
	"this", "to", "was", "were", "what", "when", "where", "which", "with",
]);

export async function recallMemory(state: MemoryState, options: MemoryRecallOptions, signal?: AbortSignal): Promise<MemoryRecallResult> {
	const query = options.query.trim();
	if (!query) throw new Error("memory_recall requires a non-empty query or path");
	if (query.length > MAX_QUERY_LENGTH) throw new Error(`memory_recall query must be at most ${MAX_QUERY_LENGTH} characters`);
	const scope = options.scope ?? "project";
	const limit = options.limit ?? DEFAULT_LIMIT;
	if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) throw new Error(`memory_recall limit must be an integer from 1 to ${MAX_LIMIT}`);
	throwIfAborted(signal);

	const documents = (await collectMemoryRecallDocuments(state, scope, signal)).filter((document) => {
		if (options.sessionId && document.sessionId !== options.sessionId) return false;
		if (options.kind && document.kind !== options.kind) return false;
		return true;
	});
	const terms = queryTerms(query);
	const stats = corpusStats(documents, terms);
	const scored = documents.map((document) => scoreDocument(document, query, terms, stats))
		.filter((result): result is { document: MemoryRecallDocument; score: number; matchedTerms: string[] } => Boolean(result))
		.sort((left, right) => right.score - left.score || left.document.path.localeCompare(right.document.path));

	return {
		query,
		scope,
		totalDocuments: documents.length,
		totalMatches: scored.length,
		hits: scored.slice(0, limit).map(({ document, score, matchedTerms }) => ({
			path: document.path,
			kind: document.kind,
			title: document.title,
			sessionId: document.sessionId,
			created: document.created,
			score: Number(score.toFixed(3)),
			matchedTerms,
			snippet: memorySnippet(document.content, terms),
		})),
	};
}

export async function expandMemorySource(state: MemoryState, requestedPath: string, signal?: AbortSignal): Promise<{ path: string; content: string; truncated: boolean }> {
	const path = requestedPath.trim().replace(/^@/, "");
	if (!path) throw new Error("memory_recall path must not be empty");
	const resolved = resolve(state.paths.projectDir, path);
	const projectRelative = relative(state.paths.projectDir, resolved);
	if (!projectRelative || projectRelative.startsWith("..") || projectRelative.startsWith("/")) {
		throw new Error("memory_recall path must stay inside the current project memory directory");
	}
	throwIfAborted(signal);
	const documents = await collectMemoryRecallDocuments(state, "project", signal);
	const document = documents.find((candidate) => candidate.path === projectRelative);
	if (!document) throw new Error(`memory_recall source is not a searchable workbench artifact: ${path}`);
	const truncated = document.content.length > MAX_EXPANDED_CHARS;
	return {
		path: document.path,
		content: truncated ? `${document.content.slice(0, MAX_EXPANDED_CHARS).trimEnd()}\n\n... [truncated; read ${document.path} directly for the remainder]\n` : document.content,
		truncated,
	};
}

export function formatMemoryRecall(result: MemoryRecallResult): string {
	if (!result.hits.length) return `No memory matches for "${result.query}" in scope ${result.scope} (${result.totalDocuments} sources searched).`;
	const header = `Memory recall: ${result.totalMatches} match${result.totalMatches === 1 ? "" : "es"} for "${result.query}" in scope ${result.scope} (${result.totalDocuments} sources searched; showing ${result.hits.length}).`;
	const hits = result.hits.map((hit, index) => {
		const metadata = [hit.kind, hit.sessionId ? `session ${hit.sessionId}` : undefined, hit.created].filter(Boolean).join(" | ");
		return `[${index + 1}] ${hit.path}\n${metadata}\n${hit.snippet}`;
	});
	return `${header}\n\n${hits.join("\n\n")}\n\nUse memory_recall with path set to an exact result path to expand its authoritative source.`;
}

export async function collectMemoryRecallDocuments(state: MemoryState, scope: MemoryRecallScope, signal?: AbortSignal): Promise<MemoryRecallDocument[]> {
	const documents: MemoryRecallDocument[] = [];
	if (scope === "project" || scope === "memory") await addSingleDocument(documents, state.paths, state.paths.memoryPath, "memory", signal);
	if (scope === "project" || scope === "session") {
		if (scope === "session") {
			await addSessionDocuments(documents, state.paths, state.session.safeId, signal, state.session.id);
		} else {
			for (const sessionId of await directoryNames(state.paths.sessionsDir)) await addSessionDocuments(documents, state.paths, sessionId, signal);
		}
	}
	if (scope === "project" || scope === "events" || scope === "session") {
		await addDirectoryDocuments(documents, state.paths, state.paths.eventsDir, "event", scope === "session" ? state.session.id : undefined, signal);
	}
	if (scope === "project" || scope === "dreams" || scope === "session") {
		await addDirectoryDocuments(documents, state.paths, state.paths.dreamsDir, "dream", scope === "session" ? state.session.id : undefined, signal, new Set(["last-run.md"]));
	}
	if (scope === "project" || scope === "digests") await addDirectoryDocuments(documents, state.paths, state.paths.eventDigestsDir, "event-digest", undefined, signal);
	return documents.sort((left, right) => left.path.localeCompare(right.path));
}

async function addSessionDocuments(documents: MemoryRecallDocument[], paths: MemoryPaths, sessionDirectory: string, signal?: AbortSignal, rawSessionId?: string): Promise<void> {
	await addSingleDocument(documents, paths, join(paths.sessionsDir, sessionDirectory, "progress.md"), "session-progress", signal, rawSessionId);
	await addSingleDocument(documents, paths, join(paths.sessionsDir, sessionDirectory, "todo.md"), "session-todo", signal, rawSessionId);
}

async function addDirectoryDocuments(documents: MemoryRecallDocument[], paths: MemoryPaths, directory: string, fallbackKind: string, sessionId: string | undefined, signal?: AbortSignal, excluded = new Set<string>()): Promise<void> {
	for (const name of await markdownFiles(directory)) {
		if (excluded.has(name)) continue;
		throwIfAborted(signal);
		const path = join(directory, name);
		const content = await readRecallDocument(paths, path);
		if (!content) continue;
		const metadata = parseMemoryEventMetadata(content);
		if (sessionId && metadata.sessionId !== sessionId) continue;
		documents.push(documentFromContent(paths, path, content, metadata.kind ?? fallbackKind, metadata.sessionId, metadata.created));
	}
}

async function addSingleDocument(documents: MemoryRecallDocument[], paths: MemoryPaths, path: string, kind: string, signal?: AbortSignal, sessionId?: string): Promise<void> {
	throwIfAborted(signal);
	const content = await readRecallDocument(paths, path);
	if (content) documents.push(documentFromContent(paths, path, content, kind, sessionId ?? sessionIdFromDocument(content)));
}

async function readRecallDocument(paths: MemoryPaths, path: string): Promise<string | undefined> {
	let projectRealPath: string;
	let documentRealPath: string;
	try {
		[projectRealPath, documentRealPath] = await Promise.all([realpath(paths.projectDir), realpath(path)]);
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return undefined;
		throw error;
	}
	const resolvedRelative = relative(projectRealPath, documentRealPath);
	if (!resolvedRelative || resolvedRelative.startsWith("..") || resolvedRelative.startsWith("/")) {
		throw new Error(`Memory recall refused because ${relativeFrom(paths.projectDir, path)} resolves outside the project memory directory`);
	}
	return readOptional(documentRealPath);
}

function sessionIdFromDocument(content: string): string | undefined {
	const value = content.match(/^Session ID:\s*(.+)$/im)?.[1]?.trim();
	return value && !/^None\.?$/i.test(value) ? value : undefined;
}

function documentFromContent(paths: MemoryPaths, path: string, content: string, kind: string, sessionId?: string, created?: string): MemoryRecallDocument {
	return {
		path: relativeFrom(paths.projectDir, path),
		kind,
		content,
		title: content.match(/^#\s+(.+)$/m)?.[1]?.trim() ?? basename(path),
		sessionId,
		created,
	};
}

async function directoryNames(directory: string): Promise<string[]> {
	try {
		const names: string[] = [];
		for (const entry of await readdir(directory, { withFileTypes: true })) if (entry.isDirectory()) names.push(entry.name);
		return names.sort();
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

async function markdownFiles(directory: string): Promise<string[]> {
	try {
		const files: string[] = [];
		for (const entry of await readdir(directory, { withFileTypes: true })) {
			if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
			const info = await stat(join(directory, entry.name));
			if (info.isFile()) files.push(entry.name);
		}
		return files.sort();
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

function queryTerms(query: string): string[] {
	const raw = query.toLowerCase().match(/[\p{L}\p{N}_.\/-]+/gu) ?? [];
	const meaningful = [...new Set(raw.filter((term) => term.length > 1 && !STOPWORDS.has(term)))];
	return meaningful.length ? meaningful : [...new Set(raw)];
}

function corpusStats(documents: MemoryRecallDocument[], terms: string[]): { documentCount: number; averageLength: number; documentFrequency: Map<string, number> } {
	const documentFrequency = new Map<string, number>();
	let totalLength = 0;
	for (const document of documents) {
		const text = searchableText(document);
		totalLength += tokenCount(text);
		for (const term of terms) if (text.includes(term)) documentFrequency.set(term, (documentFrequency.get(term) ?? 0) + 1);
	}
	return { documentCount: documents.length, averageLength: totalLength / Math.max(documents.length, 1), documentFrequency };
}

function scoreDocument(document: MemoryRecallDocument, query: string, terms: string[], stats: { documentCount: number; averageLength: number; documentFrequency: Map<string, number> }): { document: MemoryRecallDocument; score: number; matchedTerms: string[] } | undefined {
	const text = searchableText(document);
	const matchedTerms = terms.filter((term) => text.includes(term));
	if (!matchedTerms.length || (terms.length >= 2 && matchedTerms.length < 2)) return undefined;
	const length = tokenCount(text);
	let score = 0;
	for (const term of matchedTerms) {
		const frequency = occurrences(text, term);
		const documentFrequency = stats.documentFrequency.get(term) ?? 0;
		const inverseFrequency = Math.log((stats.documentCount - documentFrequency + 0.5) / (documentFrequency + 0.5) + 1);
		const saturation = (frequency * 2.2) / (frequency + 1.2 * (0.25 + 0.75 * length / Math.max(stats.averageLength, 1)));
		score += inverseFrequency * saturation;
		if (document.path.toLowerCase().includes(term)) score += 0.8;
	}
	if (text.includes(query.toLowerCase())) score += 2;
	return { document, score, matchedTerms };
}

function searchableText(document: MemoryRecallDocument): string {
	return `${document.path}\n${document.kind}\n${document.sessionId ?? ""}\n${document.title}\n${document.content}`.toLowerCase();
}

function tokenCount(text: string): number {
	return text.match(/[\p{L}\p{N}_.\/-]+/gu)?.length ?? 0;
}

function occurrences(text: string, term: string): number {
	let count = 0;
	let offset = 0;
	while ((offset = text.indexOf(term, offset)) >= 0) {
		count += 1;
		offset += term.length;
	}
	return count;
}

function memorySnippet(content: string, terms: string[]): string {
	const lines = content.split(/\r?\n/);
	const index = lines.findIndex((line) => terms.some((term) => line.toLowerCase().includes(term)));
	if (index < 0) return lines.slice(0, 3).join("\n").slice(0, 1_200);
	const start = Math.max(0, index - SNIPPET_CONTEXT_LINES);
	const end = Math.min(lines.length, index + SNIPPET_CONTEXT_LINES + 1);
	const snippet = [start > 0 ? `... (${start} lines above)` : undefined, ...lines.slice(start, end), end < lines.length ? `... (${lines.length - end} lines below)` : undefined]
		.filter((line): line is string => line !== undefined)
		.join("\n");
	return snippet.length > 1_200 ? `${snippet.slice(0, 1_180).trimEnd()}\n... [snippet truncated]` : snippet;
}

function throwIfAborted(signal?: AbortSignal): void {
	if (signal?.aborted) throw new Error("memory_recall aborted");
}

function isNodeErrorCode(error: unknown, code: string): boolean {
	return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

export type TodoStatus = "todo" | "doing" | "done" | "blocked";

export interface TodoItem {
	index: number;
	status: TodoStatus;
	text: string;
}

export interface ParsedTodo {
	title: string;
	objective?: string;
	items: TodoItem[];
}

const statusToMarker: Record<TodoStatus, string> = {
	todo: " ",
	doing: ">",
	done: "x",
	blocked: "!",
};

function markerToStatus(marker: string): TodoStatus {
	if (marker === ">") return "doing";
	if (marker.toLowerCase() === "x") return "done";
	if (marker === "!") return "blocked";
	return "todo";
}

export function parseTodo(content: string): ParsedTodo {
	const lines = content.split(/\r?\n/);
	const title = lines.find((line) => line.startsWith("# "))?.replace(/^#\s+/, "").trim() || "Untitled task";
	const objectiveStart = lines.findIndex((line) => /^##\s+Objective\s*$/i.test(line));
	let objective: string | undefined;
	if (objectiveStart >= 0) {
		const collected: string[] = [];
		for (const line of lines.slice(objectiveStart + 1)) {
			if (/^##\s+/.test(line)) break;
			if (line.trim()) collected.push(line.trim());
		}
		objective = collected.join(" ") || undefined;
	}

	let index = 1;
	let inItems = false;
	let foundItems = false;
	const items: TodoItem[] = [];
	for (const line of lines) {
		if (/^##\s+/.test(line)) {
			if (!foundItems && /^##\s+Items\s*$/i.test(line)) {
				inItems = true;
				foundItems = true;
				continue;
			}
			if (inItems) inItems = false;
		}
		if (!inItems) continue;

		const checkbox = line.match(/^\s*-\s*\[([ xX>!])\]\s+(.+)$/);
		if (checkbox) {
			items.push({ index: index++, status: markerToStatus(checkbox[1] ?? " "), text: checkbox[2]?.trim() ?? "" });
			continue;
		}
		const status = line.match(/^\s*-\s*(TODO|DOING|DONE|BLOCKED)\s*:?\s+(.+)$/i);
		if (status?.[1]) {
			items.push({
				index: index++,
				status: status[1].toLowerCase() as TodoStatus,
				text: status[2]?.trim() ?? "",
			});
		}
	}
	return { title, objective, items };
}

export function createTodoMarkdown(title: string, now = new Date()): string {
	const safeTitle = sanitizeTodoLine(title, "Todo title");
	const started = now.toISOString().slice(0, 16).replace("T", " ");
	return `# ${safeTitle || "Untitled task"}\n\nStarted: ${started}\nStatus: active\n\n## Objective\n${safeTitle || "Untitled task"}\n\n## Items\n- [>] Start work\n\n## Notes\n`;
}

export function appendTodoItem(content: string, text: string): string {
	const line = `- [ ] ${sanitizeTodoLine(text, "Todo item")}`;
	const lines = content.split(/\r?\n/);
	const headingIndex = lines.findIndex((value) => /^##\s+Items\s*$/i.test(value));
	if (headingIndex < 0) return `${content.trimEnd()}\n\n## Items\n${line}\n`;
	let insertIndex = headingIndex + 1;
	while (insertIndex < lines.length && !/^##\s+/.test(lines[insertIndex] ?? "")) insertIndex += 1;
	while (insertIndex > headingIndex + 1 && !(lines[insertIndex - 1] ?? "").trim()) insertIndex -= 1;
	lines.splice(insertIndex, 0, line);
	return lines.join("\n");
}

export function setTodoStatus(content: string, index: number, status: TodoStatus): string {
	let seen = 0;
	let found = false;
	let inItems = false;
	let foundItems = false;
	const marker = statusToMarker[status];
	const updated = content
		.split(/\r?\n/)
		.map((line) => {
			if (/^##\s+/.test(line)) {
				if (!foundItems && /^##\s+Items\s*$/i.test(line)) {
					inItems = true;
					foundItems = true;
					return line;
				}
				if (inItems) inItems = false;
			}
			if (!inItems) return line;

			if (/^\s*-\s*\[[ xX>!]\]\s+/.test(line)) {
				seen += 1;
				if (seen === index) {
					found = true;
					return line.replace(/\[[ xX>!]\]/, `[${marker}]`);
				}
				return status === "doing" ? line.replace(/\[>\]/, "[ ]") : line;
			}
			if (/^\s*-\s*(TODO|DOING|DONE|BLOCKED)\s*:?\s+/i.test(line)) {
				seen += 1;
				if (seen === index) {
					found = true;
					return line.replace(/^(\s*-\s*)(TODO|DOING|DONE|BLOCKED)(\s*:?\s+)/i, `$1${status.toUpperCase()}$3`);
				}
				return status === "doing" ? line.replace(/^(\s*-\s*)DOING(\s*:?\s+)/i, "$1TODO$2") : line;
			}
			return line;
		})
		.join("\n");
	if (!found) throw new Error(`Todo item #${index} not found`);
	return updated;
}

export function sanitizeTodoLine(value: string, label: string): string {
	const trimmed = value.trim();
	if (/\r|\n/.test(trimmed)) throw new Error(`${label} must be a single line`);
	if (/^\s{0,3}#{1,6}\s+/.test(trimmed) || /^\s*[-*+]\s*(?:\[[ xX>!]\]|TODO|DOING|DONE|BLOCKED)\b/i.test(trimmed)) {
		throw new Error(`${label} must be plain single-line text, not markdown task syntax`);
	}
	return trimmed;
}

export function slugifyTitle(title: string): string {
	return title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "task";
}

export function timestampForFile(date = new Date()): string {
	const pad = (value: number) => String(value).padStart(2, "0");
	return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}-${pad(date.getHours())}${pad(date.getMinutes())}`;
}

import { readdir } from "node:fs/promises";
import { basename, join } from "node:path";
import { readOptional, relativeFrom, type MemoryPaths } from "./paths.ts";

export const EVENT_METADATA_VERSION = "v1";
export const RELATED_EVENT_LOOKBACK_LIMIT = 100;

export interface MemoryEventMetadata {
	version: typeof EVENT_METADATA_VERSION | "legacy";
	kind?: string;
	created?: string;
	sessionId?: string;
	actorKind?: "owner" | "subagent" | "unknown";
	parentSession?: string;
	project?: string;
	sessionProgress?: string;
	sessionTodo?: string;
	memory?: string;
	sourceHashBasis?: string;
	sourceHashes: Array<{ path: string; hash: string }>;
	relatedEvents: RelatedMemoryEvents;
	memoryRefs: string[];
	digestRefs: string[];
	labels: Set<string>;
	listSections: Set<string>;
}

export interface RelatedMemoryEvents {
	previousEvent?: string;
	previousSameSessionEvent?: string;
	previousSameKindEvent?: string;
}

export interface FormatMemoryEventMetadataParams {
	kind: string;
	created: string;
	sessionId: string;
	actorKind: "owner" | "subagent" | "unknown";
	parentSession?: string;
	project: string;
	sessionProgress: string;
	sessionTodo: string;
	memory: string;
	sourceHashes: Array<{ path: string; hash: string }>;
	relatedEvents?: RelatedMemoryEvents;
	memoryRefs?: string[];
	digestRefs?: string[];
}

export function parseMemoryEventMetadata(content: string): MemoryEventMetadata {
	const header = metadataHeader(content);
	const labels = metadataLabels(header);
	const listSections = metadataListSections(header);
	const version = lineValue(header, "Event metadata") === EVENT_METADATA_VERSION ? EVENT_METADATA_VERSION : "legacy";
	return {
		version,
		kind: lineValue(header, "Kind"),
		created: lineValue(header, "Created"),
		sessionId: lineValue(header, "Session ID"),
		actorKind: parseActorKind(lineValue(header, "Actor kind")),
		parentSession: normalizeNone(lineValue(header, "Parent session")),
		project: lineValue(header, "Project"),
		sessionProgress: normalizeNone(lineValue(header, "Session progress")),
		sessionTodo: normalizeNone(lineValue(header, "Session todo")),
		memory: normalizeNone(lineValue(header, "Memory")),
		sourceHashBasis: lineValue(header, "Source hash basis"),
		sourceHashes: parseSourceHashes(header),
		relatedEvents: parseRelatedEvents(header),
		memoryRefs: parseRefs(header, "Memory refs"),
		digestRefs: parseRefs(header, "Digest refs"),
		labels,
		listSections,
	};
}

export function formatMemoryEventMetadataV1(params: FormatMemoryEventMetadataParams): string {
	const related = params.relatedEvents ?? {};
	return [
		`Event metadata: ${EVENT_METADATA_VERSION}`,
		`Kind: ${params.kind}`,
		`Created: ${params.created}`,
		`Session ID: ${params.sessionId}`,
		`Actor kind: ${params.actorKind}`,
		`Parent session: ${params.parentSession ?? "None."}`,
		`Project: ${params.project}`,
		`Session progress: ${params.sessionProgress}`,
		`Session todo: ${params.sessionTodo}`,
		`Memory: ${params.memory}`,
		`Source hash basis: pre-write state loaded before this operation.`,
		`Source hashes:`,
		...params.sourceHashes.map((source) => `- ${source.path}: ${source.hash}`),
		``,
		`Related events:`,
		`- Previous event: ${related.previousEvent ?? "None."}`,
		`- Previous same-session event: ${related.previousSameSessionEvent ?? "None."}`,
		`- Previous same-kind event: ${related.previousSameKindEvent ?? "None."}`,
		``,
		...formatRefList("Memory refs", params.memoryRefs),
		``,
		...formatRefList("Digest refs", params.digestRefs),
	].join("\n");
}

export async function findRelatedMemoryEvents(paths: MemoryPaths, params: { kind: string; sessionId: string; limit?: number }): Promise<RelatedMemoryEvents> {
	const limit = params.limit ?? RELATED_EVENT_LOOKBACK_LIMIT;
	const files = await eventFilesByFilename(paths, limit);
	const related: RelatedMemoryEvents = {};
	const latest = files[files.length - 1];
	if (latest) related.previousEvent = relativeFrom(paths.projectDir, latest);

	for (let index = files.length - 1; index >= 0; index -= 1) {
		if (related.previousSameKindEvent && related.previousSameSessionEvent) break;
		const file = files[index];
		const content = file ? await readOptional(file) : undefined;
		if (!content) continue;
		const metadata = parseMemoryEventMetadata(content);
		const relativePath = relativeFrom(paths.projectDir, file);
		if (!related.previousSameSessionEvent && metadata.sessionId === params.sessionId) related.previousSameSessionEvent = relativePath;
		if (!related.previousSameKindEvent && metadata.kind === params.kind) related.previousSameKindEvent = relativePath;
	}

	return related;
}

export async function eventFilesByFilename(paths: MemoryPaths, limit = RELATED_EVENT_LOOKBACK_LIMIT): Promise<string[]> {
	try {
		const files = (await readdir(paths.eventsDir))
			.filter((entry) => entry.endsWith(".md"))
			.sort(compareEventFilenames)
			.map((entry) => join(paths.eventsDir, entry));
		return files.slice(Math.max(0, files.length - limit));
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

function metadataHeader(content: string): string {
	const lines = content.split(/\r?\n/);
	const headingIndex = lines.findIndex((line, index) => index > 0 && /^##\s+/.test(line));
	return (headingIndex < 0 ? lines : lines.slice(0, headingIndex)).join("\n");
}

function metadataLabels(content: string): Set<string> {
	const labels = new Set<string>();
	for (const line of content.split(/\r?\n/)) {
		const match = line.match(/^([A-Z][A-Za-z ]+):(?:\s|$)/);
		if (match?.[1]) labels.add(match[1]);
	}
	return labels;
}

function metadataListSections(content: string): Set<string> {
	const sections = new Set<string>();
	for (const line of content.split(/\r?\n/)) {
		const match = line.match(/^([A-Z][A-Za-z ]+):\s*$/);
		if (match?.[1]) sections.add(match[1]);
	}
	return sections;
}

function parseSourceHashes(content: string): Array<{ path: string; hash: string }> {
	return parseListAfterLabel(content, "Source hashes")
		.map((line) => {
			const index = line.lastIndexOf(": ");
			if (index < 0) return undefined;
			const path = line.slice(0, index).trim();
			const hash = line.slice(index + 2).trim();
			return path && hash ? { path, hash } : undefined;
		})
		.filter((value): value is { path: string; hash: string } => Boolean(value));
}

function parseRelatedEvents(content: string): RelatedMemoryEvents {
	const related: RelatedMemoryEvents = {};
	for (const line of parseListAfterLabel(content, "Related events")) {
		const value = lineValue(line, "Previous event");
		const sameSession = lineValue(line, "Previous same-session event");
		const sameKind = lineValue(line, "Previous same-kind event");
		if (value) related.previousEvent = normalizeNone(value);
		if (sameSession) related.previousSameSessionEvent = normalizeNone(sameSession);
		if (sameKind) related.previousSameKindEvent = normalizeNone(sameKind);
	}
	return related;
}

function parseRefs(content: string, label: string): string[] {
	return parseListAfterLabel(content, label).map(normalizeNone).filter((value): value is string => Boolean(value));
}

function parseListAfterLabel(content: string, label: string): string[] {
	const lines = content.split(/\r?\n/);
	const start = lines.findIndex((line) => line.trim() === `${label}:`);
	if (start < 0) return [];
	const values: string[] = [];
	for (const line of lines.slice(start + 1)) {
		if (!line.trim()) break;
		const item = line.match(/^\s*-\s+(.+)$/);
		if (!item) break;
		values.push(item[1]?.trim() ?? "");
	}
	return values.filter(Boolean);
}

function formatRefList(label: string, refs: string[] | undefined): string[] {
	const values = refs?.filter((ref) => normalizeNone(ref)) ?? [];
	return [`${label}:`, ...(values.length ? values.map((ref) => `- ${ref}`) : ["- None."])];
}

function lineValue(content: string, label: string): string | undefined {
	const escaped = label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const match = content.match(new RegExp(`^${escaped}:\\s*(.*)$`, "im"));
	return match?.[1]?.trim() || undefined;
}

function normalizeNone(value: string | undefined): string | undefined {
	if (!value || /^None\.?$/i.test(value.trim())) return undefined;
	return value.trim();
}

function parseActorKind(value: string | undefined): "owner" | "subagent" | "unknown" | undefined {
	if (value === "owner" || value === "subagent" || value === "unknown") return value;
	return value ? "unknown" : undefined;
}

function compareEventFilenames(a: string, b: string): number {
	const left = eventFilenameSortKey(a);
	const right = eventFilenameSortKey(b);
	return left.localeCompare(right);
}

function eventFilenameSortKey(path: string): string {
	const name = basename(path);
	const timestamp = name.match(/^(\d{8}T\d{6}Z)-/)?.[1];
	return `${timestamp ?? "99999999T999999Z"}-${name}`;
}

function isNodeErrorCode(error: unknown, code: string): boolean {
	return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}

import { execFile } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import { access, mkdir, readdir, readFile, stat, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { basename, dirname, join, relative, resolve } from "node:path";
import { promisify } from "node:util";
import { withFileMutationQueue } from "@earendil-works/pi-coding-agent";

const execFileAsync = promisify(execFile);

export const MEMORY_LAYOUT_MARKER = "<!-- pi-memory-workbench-layout: session-events-v1 -->";

export type MemoryMode = "owner" | "readonly";

export interface MemorySessionIdentity {
	id: string;
	safeId: string;
	displayName?: string;
	sessionFile?: string;
	parentSession?: string;
	actorKind: "owner" | "subagent" | "unknown";
	memoryMode: MemoryMode;
}

export interface FileSnapshot {
	exists: boolean;
	hash: string | null;
}

export interface MemoryPaths {
	projectKey: string;
	projectDir: string;
	progressPath: string;
	memoryPath: string;
	sessionsDir: string;
	sessionDir: string;
	sessionProgressPath: string;
	sessionTodoPath: string;
	eventsDir: string;
	eventDigestsDir: string;
	todosDir: string;
	currentTodoPath: string;
	dreamsDir: string;
	lastRunPath: string;
	globalMemoryPath: string;
}

export async function resolveMemoryPaths(cwd: string, session: MemorySessionIdentity): Promise<MemoryPaths> {
	let root: string;
	try {
		const { stdout } = await execFileAsync("git", ["-C", cwd, "rev-parse", "--show-toplevel"]);
		root = stdout.trim() || cwd;
	} catch {
		// Git discovery is optional; any failure falls back to a cwd-based project key.
		root = cwd;
	}

	const projectKey = sanitizePathSegment(basename(root), "default");
	const memoryRoot = join(homedir(), ".pi", "agent", "memory");
	const projectDir = join(memoryRoot, projectKey);
	const sessionsDir = join(projectDir, "sessions");
	const sessionDir = join(sessionsDir, session.safeId);
	const todosDir = join(projectDir, "todos");
	const dreamsDir = join(projectDir, "dreams");
	const eventsDir = join(projectDir, "events");
	const eventDigestsDir = join(projectDir, "event-digests");

	return {
		projectKey,
		projectDir,
		progressPath: join(projectDir, "progress.md"),
		memoryPath: join(projectDir, "memory.md"),
		sessionsDir,
		sessionDir,
		sessionProgressPath: join(sessionDir, "progress.md"),
		sessionTodoPath: join(sessionDir, "todo.md"),
		eventsDir,
		eventDigestsDir,
		todosDir,
		currentTodoPath: join(todosDir, "current.md"),
		dreamsDir,
		lastRunPath: join(dreamsDir, "last-run.md"),
		globalMemoryPath: join(memoryRoot, "global.md"),
	};
}

export async function ensureMemoryDirs(paths: MemoryPaths): Promise<void> {
	await mkdir(paths.sessionDir, { recursive: true });
	await mkdir(paths.eventsDir, { recursive: true });
	await mkdir(paths.eventDigestsDir, { recursive: true });
	await mkdir(paths.todosDir, { recursive: true });
	await mkdir(paths.dreamsDir, { recursive: true });
}

export async function readOptional(path: string): Promise<string | undefined> {
	try {
		return await readFile(path, "utf8");
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return undefined;
		throw error;
	}
}

export async function exists(path: string): Promise<boolean> {
	try {
		await access(path);
		return true;
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return false;
		throw error;
	}
}

export async function fileSnapshot(path: string): Promise<FileSnapshot> {
	const content = await readOptional(path);
	return content === undefined ? { exists: false, hash: null } : { exists: true, hash: hashContent(content) };
}

export function hashContent(content: string): string {
	return `sha256:${createHash("sha256").update(content, "utf8").digest("hex")}`;
}

export async function mutateFile(path: string, update: (current: string) => string | Promise<string>): Promise<void> {
	await withFileMutationQueue(path, async () => {
		await mkdir(dirname(path), { recursive: true });
		const current = await readOptional(path) ?? "";
		await writeFile(path, await update(current), "utf8");
	});
}

export async function mutateFileIfUnchanged(path: string, expected: FileSnapshot | undefined, update: (current: string) => string | Promise<string>): Promise<void> {
	await withFileMutationQueue(path, async () => {
		await mkdir(dirname(path), { recursive: true });
		const current = await readOptional(path);
		const actual: FileSnapshot = current === undefined ? { exists: false, hash: null } : { exists: true, hash: hashContent(current) };
		if (expected && (actual.exists !== expected.exists || actual.hash !== expected.hash)) {
			throw new Error(`Memory conflict for ${path}: file changed since it was read. Re-read memory and retry.`);
		}
		await writeFile(path, await update(current ?? ""), "utf8");
	});
}

export async function writeNewFile(path: string, content: string): Promise<string> {
	for (let attempt = 1; attempt <= 100; attempt += 1) {
		const candidate = numberedPath(path, attempt);
		try {
			return await writeExclusiveFile(candidate, content);
		} catch (error) {
			if (isNodeErrorCode(error, "EEXIST")) continue;
			throw error;
		}
	}
	throw new Error(`Could not create a unique file for ${path}`);
}

export async function writeExclusiveFile(path: string, content: string): Promise<string> {
	await withFileMutationQueue(path, async () => {
		await mkdir(dirname(path), { recursive: true });
		await writeFile(path, content, { encoding: "utf8", flag: "wx" });
	});
	return path;
}

export async function writeMemoryEventFile(paths: MemoryPaths, sessionSafeId: string, kind: string, content: string): Promise<string> {
	const fileName = `${compactTimestamp()}-${sanitizePathSegment(sessionSafeId, "session")}-${sanitizePathSegment(kind, "event")}-${randomBytes(3).toString("hex")}.md`;
	return writeNewFile(join(paths.eventsDir, fileName), content);
}

export async function recentMarkdownFiles(dir: string, limit: number, options: { exclude?: string[] } = {}): Promise<Array<{ path: string; mtimeMs: number }>> {
	try {
		const excluded = new Set(options.exclude ?? []);
		const files: Array<{ path: string; mtimeMs: number }> = [];
		for (const entry of await readdir(dir)) {
			if (!entry.endsWith(".md") || excluded.has(entry)) continue;
			const fullPath = join(dir, entry);
			const info = await stat(fullPath);
			if (info.isFile()) files.push({ path: fullPath, mtimeMs: info.mtimeMs });
		}
		return files.sort((a, b) => b.mtimeMs - a.mtimeMs).slice(0, limit);
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

export async function recentSessionProgressFiles(paths: MemoryPaths, limit: number): Promise<Array<{ sessionSafeId: string; path: string; mtimeMs: number }>> {
	try {
		const files: Array<{ sessionSafeId: string; path: string; mtimeMs: number }> = [];
		for (const entry of await readdir(paths.sessionsDir)) {
			const progressPath = join(paths.sessionsDir, entry, "progress.md");
			try {
				const info = await stat(progressPath);
				if (info.isFile()) files.push({ sessionSafeId: entry, path: progressPath, mtimeMs: info.mtimeMs });
			} catch (error) {
				if (!isNodeErrorCode(error, "ENOENT") && !isNodeErrorCode(error, "ENOTDIR")) throw error;
			}
		}
		return files.sort((a, b) => b.mtimeMs - a.mtimeMs).slice(0, limit);
	} catch (error) {
		if (isNodeErrorCode(error, "ENOENT")) return [];
		throw error;
	}
}

export function relativeFrom(baseDir: string, path: string): string {
	const value = relative(baseDir, path);
	return value && !value.startsWith("..") && !value.startsWith("/") ? value : path;
}

export function resolveTodoPointer(paths: MemoryPaths, pointer: string): string {
	const raw = pointer.replace(/^["']|["']$/g, "").trim();
	if (!raw) return paths.currentTodoPath;
	const resolved = resolve(paths.todosDir, raw);
	const value = relative(paths.todosDir, resolved);
	if (value.startsWith("..") || value.startsWith("/") || value === "") {
		throw new Error(`Active todo pointer must stay inside ${paths.todosDir}: ${raw}`);
	}
	return resolved;
}

export function sanitizePathSegment(value: string | undefined, fallback: string): string {
	const raw = (value ?? "").trim();
	const sanitized = raw.replace(/[^a-zA-Z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");
	const base = sanitized || fallback;
	if (raw && sanitized === raw && sanitized.length <= 120) return sanitized;
	const hash = createHash("sha256").update(raw || fallback, "utf8").digest("hex").slice(0, 8);
	return `${base.slice(0, 111).replace(/-+$/g, "")}-${hash}`;
}

export function compactTimestamp(date = new Date()): string {
	return date.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");
}

function numberedPath(path: string, attempt: number): string {
	if (attempt === 1) return path;
	return path.endsWith(".md") ? `${path.slice(0, -3)}-${attempt}.md` : `${path}-${attempt}`;
}

function isNodeErrorCode(error: unknown, code: string): boolean {
	return Boolean(error && typeof error === "object" && "code" in error && error.code === code);
}
